'use strict';
const paths={home:'M3 10l9-7 9 7v10H4V10m5 10v-7h6v7',plan:'M5 5h14v16H5zM8 3v4m8-4v4M5 10h14m-10 4h2m3 0h2m-7 3h2',community:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 7',profile:'M20 21v-2a7 7 0 0 0-14 0v2M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',activity:'M2 12h5l3-9 4 18 3-9h5',search:'M21 21l-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0',arrow:'M5 12h14m-6-6 6 6-6 6',back:'m15 18-6-6 6-6',chevron:'m9 18 6-6-6-6',flame:'M12 3c2 5 6 6 6 11a6 6 0 0 1-12 0c0-3 2-6 4-8 0 3 1 4 2 5 2-3 2-5 0-8',play:'m9 5 11 7-11 7z',clock:'M12 8v5l3 2M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 4 4 1 2 5-3 3 1 4-5 3-3-3-4 1-4-4 2-4-2-4 4-2z',bookmark:'M6 3h12v19l-6-4-6 4z',share:'M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8',trophy:'M7 3h10v7a5 5 0 0 1-10 0V3m0 3H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 2v6m-4 0h8',leaf:'M20 3C7 3 2 8 5 16c8 6 16-1 15-13M4 21 16 8',weight:'M5 7h14l2 14H3L5 7m4 0V5a3 3 0 0 1 6 0v2',dumbbell:'m6 5 13 13M3 7l4-4M2 11l9-9m2 20 9-9m-5 8 4-4M7 15l8-8',message:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4',pause:'M8 5v14M16 5v14',skip:'m5 5 10 7-10 7zM19 5v14',sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M5 5 3 3m18 18-2-2M5 19l-2 2M21 3l-2 2M12 17a5 5 0 1 0 0-10 5 5 0 0 0 0 10',globe:'M2 12h20M12 2c6 5 6 15 0 20-6-5-6-15 0-20M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4m-5 10 3 3 7-7',device:'M7 2h10v20H7zM10 18h4',mail:'M3 5h18v14H3zM3 5l9 8 9-8',more:'M5 12h.1M12 12h.1M19 12h.1',edit:'m4 16 12-12 4 4L8 20H4v-4m10-10 4 4',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',camera:'M3 6h4l2-3h6l2 3h4v14H3zM12 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M9 16a5 5 0 0 1 6 0M12 20h.01'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.activity}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={loggedIn:false,onboarded:false,name:'Alex Morgan',email:'alex@example.com',lang:'en',unit:'metric',theme:'light',member:false,goal:'Stay active',age:28,height:175,weight:72.4,target:70,experience:'Beginner',duration:20,frequency:4,equipment:'Bodyweight',injury:'None',workouts:[],hearts:[{id:1,value:68,context:'Resting',date:'18 Sep, 08:42',note:''}],weights:[{id:1,value:72.4,date:'18 Sep'}],joined:false,checkins:0,likes:{},favorites:[],posts:[],comments:{},devices:{},permissions:{},notifications:{},draft:'',stepsGoal:8000,following:[],planStatus:'active',read:[],searches:[]};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('pulsefit-v1')||'{}')}}catch{state={...initial}};
let page='home',param='',prev=[],timer=null,toastTimer=null,selectedDay=4,period='Week',communityTab='For You',filter='All',onboardStep=0,workIndex=0,seconds=30,paused=false,rest=false,measureProgress=0,measureIssue='',scrolls={},draftAnswers={...state},selectedPrice='Yearly',flowMode='onboard';
const save=()=>{localStorage.setItem('pulsefit-v1',JSON.stringify(state))};
let previousFocus=null;const t=(key,vars)=>PF_I18N.translate(key,state.lang,vars);
const photo='assets/fitness-hero.webp',runPhoto='assets/running.webp';
const ib=(n,action,label=n)=>`<button class="icon-button" onclick="${esc(action)}" aria-label="${esc(t(label))}">${icon(n)}</button>`;
const btn=(label,action,cls='primary',disabled=false)=>`<button class="${cls}" onclick="${esc(action)}" ${disabled?'disabled':''}>${t(label)}</button>`;
const header=(title,action='')=>`<div class="page-header">${ib('back','back()','Back')}<h2>${t(title)}</h2>${action||'<span class="spacer"></span>'}</div>`;
const section=(title,more='',action='')=>`<div class="section-head"><h3>${t(title)}</h3>${more?btn(more,action,'text-button'):''}</div>`;
const row=(label,sub,ico,action,end='')=>`<button class="list-row" onclick="${esc(action)}"><span class="list-icon">${icon(ico)}</span><span class="list-copy"><strong>${t(label)}</strong>${sub?`<small>${t(sub)}</small>`:''}</span>${end||icon('chevron')}</button>`;
const field=(label,id,value='',type='text',extra='')=>`<label class="form-field"><span>${t(label)}</span><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,id,opts,value)=>`<label class="form-field"><span>${t(label)}</span><select id="${id}">${opts.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${t(x)}</option>`).join('')}</select></label>`;
const tabs=(items,current,action)=>`<div class="tabs">${items.map(x=>btn(x,`${action}('${x}')`,x===current?'active':'')).join('')}</div>`;
const spark=(color='#719666')=>`<svg class="spark" viewBox="0 0 120 35"><path d="M0 23 10 20 17 24 23 12 29 20 35 17 41 28 47 9 53 20 60 15 68 18 77 7 85 13 94 10 105 15 120 3" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const healthNote=()=>`<p class="disclaimer">${t('For wellness reference only. Not a medical diagnosis.')}<br>${t('Simulated demo data')}</p>`;
function chart(vals=[44,55,48,66,60,74,82],bars=false){let max=Math.max(...vals,1);return `<svg class="chart" viewBox="0 0 290 145" role="img" aria-label="${t('Seven-day trend')}">${[20,55,90].map(y=>`<path d="M12 ${y}H284" stroke="var(--line)" stroke-dasharray="3 4"/>`).join('')}${bars?vals.map((v,i)=>`<rect x="${17+i*39}" y="${112-v/max*92}" width="17" height="${v/max*92}" rx="6" fill="${i===6?'var(--green)':'#c9ddb1'}"/>`).join(''):`<path d="${vals.map((v,i)=>`${i?'L':'M'}${15+i*43} ${108-v/max*82}`).join(' ')}" stroke="#7ea059" stroke-width="3" fill="none" stroke-linecap="round"/>${vals.map((v,i)=>`<circle cx="${15+i*43}" cy="${108-v/max*82}" r="3.5" fill="#7ea059"/>`).join('')}`}${Array.from({length:7},(_,i)=>PF_I18N.date(new Date(2026,8,14+i),state.lang,{weekday:'narrow'})).map((x,i)=>`<text x="${bars?25+i*39:15+i*43}" y="138" text-anchor="middle">${x}</text>`).join('')}</svg>`}
function toast(msg){let el=document.getElementById('toast');el.textContent=t(msg);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function go(p,arg=''){scrolls[page]=document.getElementById('app').scrollTop;prev.push({page,param,scroll:scrolls[page]});page=p;param=arg;history.pushState({page,param},'',`#${p}${arg?'='+encodeURIComponent(arg):''}`);render();document.getElementById('app').scrollTop=0}
function back(){if(document.getElementById('overlay').innerHTML){closeSheet();return}if(page==='compose'&&document.getElementById('posttext')?.value){state.draft=document.getElementById('posttext').value;save();sheet('Save your draft?','Your writing will be here when you return.',btn('Save draft',"closeSheet();backNow()")+btn('Discard',"state.draft='';save();closeSheet();backNow()",'secondary'));return}backNow()}
function backNow(){const last=prev.pop()||{page:'home',param:'',scroll:0};page=last.page;param=last.param;history.replaceState({page,param},'',`#${page}`);render();document.getElementById('app').scrollTop=last.scroll||0}
function nav(p){scrolls[page]=document.getElementById('app').scrollTop;if(page===p){document.getElementById('app').scrollTo({top:0,behavior:'smooth'});return}page=p;param='';prev=[];history.pushState({page},'',`#${p}`);render();document.getElementById('app').scrollTop=scrolls[p]||0}
window.onpopstate=()=>{backNow()};
function sheet(title,body,actions){previousFocus=document.activeElement;document.getElementById('app').inert=true;document.getElementById('nav').inert=true;document.getElementById('overlay').innerHTML=`<div class="scrim" onclick="if(event.target===this)closeSheet()"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(t(title))}"><div class="sheet-handle"></div><div class="row between"><h2>${t(title)}</h2>${ib('close','closeSheet()','Close')}</div><p>${t(body)}</p>${actions}</section></div>`;document.querySelector('.sheet button')?.focus()}
function closeSheet(){document.getElementById('overlay').innerHTML='';document.getElementById('app').inert=false;document.getElementById('nav').inert=false;previousFocus?.focus?.()}
function confirmAction(title,action){sheet(title,'This action changes your saved demo data.',btn('Confirm',`closeSheet();${action}`)+btn('Cancel','closeSheet()','secondary'))}
function home(){const hr=state.hearts[0]?.value||'—';return `<div class="row between"><button class="row" style="background:none;padding:0" onclick="nav('profile')"><span class="avatar">AM</span><span style="text-align:left"><span class="greeting">${t('Good morning,')}</span><span class="greeting-name" style="display:block">${esc(state.name.split(' ')[0])} ${icon('sun').replace('class="icon','style="width:14px;height:14px;vertical-align:middle" class="icon')}</span></span></button><div class="row" style="gap:4px">${ib('search',"go('search')",'Search')}${ib('bell',"go('messages')",'Notifications')}</div></div><div class="intro"><div class="row between"><h2>${t('Your daily rhythm')}</h2><button class="pill" onclick="go('streak')">${icon('flame')} 7 ${t('days')}</button></div><p>${t('Friday, 18 September')} <span style="padding:0 5px">·</span> ${t('A good day to feel good.')}</p></div><div class="wellness"><div class="wellness-top"><span class="eyebrow">${t('DAILY WELLNESS')}</span><button class="text-button" onclick="go('wellness')" aria-label="${t('Wellness details')}">${icon('arrow')}</button></div><button class="wellness-main" style="background:none;color:inherit;width:100%;padding:0;text-align:left" onclick="go('wellness')"><div><div class="score-number">${82+Math.min(state.workouts.length*2,16)}<small>/100</small></div><p class="score-caption"><b>↗ 8 ${t('pts')}</b> ${t('from yesterday')}</p></div><div class="ring"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="49" stroke="#ffffff15"/><circle cx="60" cy="60" r="49" stroke="#d9f492" stroke-dasharray="249 308"/><circle cx="60" cy="60" r="37" stroke="#ffffff15" stroke-width="6"/><circle cx="60" cy="60" r="37" stroke="#9abfb1" stroke-dasharray="158 233" stroke-width="6"/></svg><div class="ring-center">${icon('leaf')}<span>${t('In balance')}</span></div></div></button><div class="wellness-stats"><button onclick="go('activity','Steps')"><strong>6,248</strong><small>${t('Steps')} / ${(state.stepsGoal/1000).toFixed(0)}k</small></button><button onclick="go('activity','Active minutes')"><strong>${32+state.workouts.reduce((a,b)=>a+b.minutes,0)}<small> ${t('min')}</small></strong><small>${t('Active time')}</small></button><button onclick="go('activity','Calories')"><strong>${energy(284+state.workouts.length*145)}<small> ${energyUnit()}</small></strong><small>${t('Energy burned')}</small></button></div></div>${section('Made for today','View plan',"nav('plan')")}<div class="workout-card"><button class="workout-cover" style="width:100%;display:block;padding:0" onclick="go('workout','Full body flow')"><img src="${photo}" alt="Woman stretching in a bright studio" onerror="this.style.display='none'"><span class="cover-shade"></span><span class="cover-label">${t('YOUR DAILY RESET')}</span><span class="cover-action">${icon('play')}</span></button><div class="workout-info"><div class="row between"><h3>${t('Full body flow')}</h3>${icon('arrow')}</div><p>${t('20 min')} &nbsp;·&nbsp; ${t('Beginner')} &nbsp;·&nbsp; ${t('No equipment')}</p></div></div>${section('In tune with you','See all',"go('data')")}<div class="grid2"><button class="card card-button" onclick="go('heart')"><span class="metric-label">${icon('heart')} ${t('Heart rate')}</span><div class="metric-number">${hr} <small>bpm</small></div>${spark('#c17b70')}<p class="metric-footer">${t('Resting')} · 08:42</p></button><button class="card card-button" onclick="go('body')"><span class="metric-label">${icon('weight')} ${t('Body balance')}</span><div class="metric-number">${weight(state.weight)} <small>${state.unit==='metric'?'kg':'lb'}</small></div>${spark()}<p class="metric-footer">−0.6 ${state.unit==='metric'?'kg':'lb'} · ${t('this week')}</p></button></div>${section('A little perspective','View all',"go('insights')")}<button class="card card-button mint" onclick="go('report')"><span class="eyebrow">${t('YOUR WEEK IN REVIEW')}</span><h3 style="margin:12px 0 8px">${t('Small steps. Real progress.')}</h3><div class="row between"><p class="muted" style="font-size:12px">${t('Your weekly health report is ready.')}</p>${icon('arrow')}</div></button>${healthNote()}`}
function weight(v){return PF_I18N.number(state.unit==='metric'?v:v*2.20462,state.lang,{minimumFractionDigits:1,maximumFractionDigits:1})}
const screens={home};
function render(){clearInterval(timer);timer=null;document.querySelector('.device').classList.toggle('dark',state.theme==='dark');document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';const primary=['home','plan','community','profile'].includes(page);document.getElementById('app').classList.toggle('has-nav',primary);document.getElementById('nav').style.display=primary?'grid':'none';document.getElementById('nav').innerHTML=['home','plan','community','profile'].map(x=>`<button class="${page===x?'active':''}" onclick="nav('${x}')"><span class="nav-icon">${icon(x)}</span>${t(x[0].toUpperCase()+x.slice(1))}</button>`).join('');document.getElementById('app').innerHTML=`<div class="page">${(screens[page]||(()=>header(page)+`<div class="card">${t('Your wellness journey, one step at a time.')}</div>`))()}</div>`;if(typeof afterRender==='function')afterRender()}
// Onboarding and account flows
screens.splash=()=>`<div class="screen-center" style="padding-top:200px"><div class="circle-icon" style="animation:breathe 1.2s infinite">${icon('activity')}</div><h2>PulseFit</h2><p class="subtitle">${t('Finding your rhythm…')}</p></div>`;
screens.welcome=()=>`<div class="welcome"><div class="row between"><span class="welcome-brand">${icon('activity')} PulseFit</span>${btn('Explore demo',"nav('home')",'text-button')}</div><div class="welcome-visual"><img src="${photo}" alt="Mindful movement in a sunlit studio"><span class="welcome-tag">${icon('leaf')} ${t('A little every day.')}</span></div><h1 class="welcome-title">${t('Build a healthier rhythm')}</h1><p>${t('Movement, balance and a little more you.')}</p>${btn('Continue with Apple',"mockLogin('Apple')")}${btn('Continue with Google',"mockLogin('Google')",'secondary')}${btn('Continue with Email',"go('login')",'secondary')}${btn('Continue as Guest',"startOnboarding()",'text-button',false)}<p class="disclaimer">${t('By continuing, you agree to our')} <button class="text-button" onclick="go('legal','Terms of Service')">${t('Terms')}</button> & <button class="text-button" onclick="go('legal','Privacy Policy')">${t('Privacy')}</button></p></div>`;
function mockLogin(provider){sheet('Demo sign-in',`${provider} sign-in is simulated. No external account is connected.`,btn('Continue',"state.loggedIn=true;save();closeSheet();startOnboarding()"))}
function startOnboarding(){flowMode='onboard';draftAnswers={...state,goal:''};onboardStep=0;go('onboarding')}
screens.login=()=>header('Welcome back')+`<div class="screen-center"><div class="circle-icon">${icon('profile')}</div><h2>${t('Good to see you again.')}</h2><p class="subtitle">${t('Your next small step starts here.')}</p></div>`+btn('Log in','login()')+`<p class="disclaimer">${t('Demo login · no account or email required')}</p>`;
function login(){state.loggedIn=true;state.onboarded=true;save();toast('Signed in successfully');nav('home')}
screens.register=()=>header('Create account')+field('Name','name','')+field('Email','email','','email')+field('Password','password','','password')+`<div id="formerror" class="error"></div>`+btn('Create account',"if(val('name').trim())state.name=val('name');login()");
screens.reset=()=>header('Reset password')+`<p class="subtitle">${t('Enter your email to receive a demo verification code.')}</p>`+field('Email','email',state.email,'email')+btn('Send code',"go('verify')");
screens.verify=()=>header('Verify your email')+`<p class="subtitle">${t('For this demo, enter 123456.')}</p>`+field('Verification code','code','','text','inputmode="numeric" maxlength="6"')+field('New password','newpassword','','password')+btn('Reset password',"if(val('code')==='123456'&&val('newpassword').length>=6){toast('Password reset successfully');go('login')}else toast('Check your code and use at least 6 characters')");
const val=id=>document.getElementById(id)?.value||'';
const goals=['Lose weight','Build muscle','Stay active','Improve endurance','Reduce stress','Monitor health'];
function option(label,current,action,sub=''){return `<button class="option ${label===current?'selected':''}" onclick="${esc(action)}"><span>${t(label)}${sub?`<small class="muted" style="display:block;margin-top:5px">${t(sub)}</small>`:''}</span><span class="check">${label===current?'✓':''}</span></button>`}
screens.onboarding=()=>{let content='';const titles=['What brings you here?','Let’s get to know you.','Make movement yours.','Find your weekly rhythm.','Your health. Your choice.'];if(onboardStep===0)content=`<p class="subtitle">${t('Choose the goal that feels right for you.')}</p><div class="stack">${goals.map(g=>option(g,draftAnswers.goal,`draftAnswers.goal='${g}';render()`)).join('')}</div>`;if(onboardStep===1)content=select('Gender','gender',['Prefer not to say','Woman','Man','Non-binary'],draftAnswers.gender||'Prefer not to say')+field('Age','age',draftAnswers.age,'number')+tabs(['Metric','Imperial'],draftAnswers.unit==='metric'?'Metric':'Imperial','onboardUnits')+`<div class="grid2">${field(draftAnswers.unit==='metric'?'Height (cm)':'Height (ft)','height',draftAnswers.unit==='metric'?draftAnswers.height:(draftAnswers.height/30.48).toFixed(2),'number','step="0.01"')}${field(draftAnswers.unit==='metric'?'Weight (kg)':'Weight (lb)','weight',draftAnswers.unit==='metric'?draftAnswers.weight:(draftAnswers.weight*2.20462).toFixed(1),'number','step="0.1"')}</div>`+field('Target weight','target',draftAnswers.unit==='metric'?draftAnswers.target:(draftAnswers.target*2.20462).toFixed(1),'number','step="0.1"')+`<p id="formerror" class="error"></p>`;if(onboardStep===2)content=`<p class="subtitle">${t('A plan that fits your experience and your life.')}</p>`+select('Experience','experience',['Beginner','Intermediate','Advanced'],draftAnswers.experience)+select('Session length','duration',['10','20','30','45','60'],String(draftAnswers.duration))+select('Equipment','equipment',['Bodyweight','Dumbbells','Full gym'],draftAnswers.equipment)+select('Preferred movement','movement',['Strength & mobility','Yoga','Running','HIIT'],draftAnswers.movement||'Strength & mobility')+field('Injuries or limitations','injury',draftAnswers.injury);if(onboardStep===3)content=`<p class="subtitle">${t('Consistency beats intensity. Start with what feels realistic.')}</p><div class="circle-icon">${icon('plan')}</div><div class="stack">${[2,3,4,5,6].map(n=>option(`${n} ${t('days per week')}`,`${draftAnswers.frequency} ${t('days per week')}`,`draftAnswers.frequency=${n};render()`,n===4?'Recommended for you':'')).join('')}</div>`;if(onboardStep===4)content=`<p class="subtitle">${t('You decide what to share. You can change this anytime in Settings.')}</p><div class="card">${['Notifications','Camera','Apple Health / Health Connect','Motion & Fitness'].map((x,i)=>`<div class="list-row"><span class="list-icon">${icon(['bell','camera','heart','activity'][i])}</span><span class="list-copy"><strong>${t(x)}</strong><small>${t('Optional · simulated permission')}</small></span><button aria-label="${t(x)}" class="switch ${draftAnswers.permissions[x]?'on':''}" onclick="draftAnswers.permissions={...draftAnswers.permissions,'${x}':!draftAnswers.permissions['${x}']};render()"></button></div>`).join('')}</div><p class="disclaimer">${t('Skipping permissions will not block your plan.')}</p>`;return header('Your personal plan')+`<div class="bar"><span style="width:${(onboardStep+1)*20}%"></span></div><p class="step-label">${t('STEP')} ${onboardStep+1} / 5</p><h2 class="big-title">${t(titles[onboardStep])}</h2>${content}<div class="onboarding-bottom">${btn(onboardStep===4?'Build my plan':'Next','onboardNext()','primary',onboardStep===0&&!draftAnswers.goal)}${onboardStep?btn('Previous step','onboardStep--;render()','text-button'):''}</div>`};
function onboardUnits(u){draftAnswers.unit=u==='Metric'?'metric':'imperial';render()}
function onboardNext(){if(onboardStep===1){let a=+val('age'),h=+val('height'),w=+val('weight'),tg=+val('target');if(draftAnswers.unit==='imperial'){h*=30.48;w/=2.20462;tg/=2.20462}if(a<18||a>100||h<100||h>240||w<30||w>300||tg<30||tg>300){document.getElementById('formerror').textContent=t('Check your age (18–100), height and weight.');return}Object.assign(draftAnswers,{age:a,height:h,weight:w,target:tg,gender:val('gender')})}if(onboardStep===2)Object.assign(draftAnswers,{experience:val('experience'),duration:+val('duration'),equipment:val('equipment'),movement:val('movement'),injury:val('injury')});if(onboardStep<4){onboardStep++;render();document.getElementById('app').scrollTop=0}else{Object.assign(state,draftAnswers);save();go('generating')}}
screens.generating=()=>header('Your personal plan')+`<div class="screen-center"><div class="circle-icon" style="animation:breathe 1.3s infinite">${icon('leaf')}</div><h2>${t('Finding your rhythm…')}</h2><p class="subtitle">${t('Bringing your goals, preferences and weekly routine together.')}</p><div class="bar"><span id="generatebar" style="width:12%;transition:width 2s"></span></div></div>`;
screens.result=()=>header('Made for you')+`<div class="circle-icon">${icon('check')}</div><h2 class="big-title" style="text-align:center">${t('Your next chapter starts here.')}</h2><p class="subtitle" style="text-align:center">${t('A balanced 4-week plan to build a lasting habit.')}</p><div class="plan-hero"><span class="eyebrow">${t('YOUR PERSONAL PLAN')}</span><h2 style="margin-top:12px">${t(state.goal)}</h2><p>${state.frequency} ${t('days per week')} · ${state.duration} ${t('min')} · ${t(state.experience)}</p><div class="bar"><span style="width:25%"></span></div></div><div class="card mt"><h3>${t('Progress at your pace')}</h3>${chart([20,32,42,48,64,70,80])}<p class="muted tiny">${t('Illustrative progress, not a guaranteed outcome.')}</p></div>${btn(flowMode==='newplan'?'Confirm new plan':'View my plan',flowMode==='newplan'?"confirmAction('Replace current plan?',\"state.planStatus='active';save();nav('plan')\")":"go('paywall')",'primary mt')}${btn('Edit answers','onboardStep=0;go("onboarding")','text-button')}`;
const prices={Weekly:['€4.99','week'],Monthly:['€12.99','month'],Yearly:['€59.99','year']};
screens.paywall=()=>header('PulseFit Plus',ib('close',"finishOnboarding()",'Close'))+`<div class="circle-icon">${icon('leaf')}</div><h2 class="big-title" style="text-align:center">${t('A little more support.<br>A lot more possibility.')}</h2><p class="subtitle" style="text-align:center">${t('Your first 7 days are on us.')}</p><div class="stack" style="margin-bottom:20px">${['Personal plans that grow with you','Unlimited workouts & programmes','Deeper health insights'].map(x=>`<div class="row">${icon('check')}<span>${t(x)}</span></div>`).join('')}</div>${Object.entries(prices).map(([p,[price,unit]])=>`<button class="option price-option ${selectedPrice===p?'selected':''}" onclick="selectedPrice='${p}';render()"><span><strong>${t(p)}</strong>${p==='Yearly'?`<small style="display:block;margin-top:5px">${t('Best value · €5.00 / month')}</small>`:''}</span><span class="price">${price}<small> / ${t(unit)}</small></span></button>`).join('')}${btn('Start free trial','payment()','primary mt')}<p class="disclaimer">${t('7 days free, then')} ${prices[selectedPrice][0]} / ${t(prices[selectedPrice][1])}. ${t('Cancel anytime before renewal. Demo only — no charge.')}</p>${btn('Restore purchase','restore()','text-button')}${btn('Terms',"go('legal','Terms of Service')",'text-button')} · ${btn('Privacy',"go('legal','Privacy Policy')",'text-button')}`;
function payment(){sheet('Confirm your trial',`${t(selectedPrice)} · ${prices[selectedPrice][0]} / ${t(prices[selectedPrice][1])}. ${t('This is a simulated purchase. No payment details are required.')}`,btn('Confirm trial',"state.member=true;state.subscription=selectedPrice;state.onboarded=true;save();closeSheet();go('paymentSuccess')")+btn('Cancel','closeSheet()','secondary'))}
function finishOnboarding(){state.onboarded=true;save();nav('home')}
function restore(){toast('Checking demo purchases…');setTimeout(()=>toast(state.member?'Your membership has been restored':'No previous demo purchases found'),900)}
screens.paymentSuccess=()=>header('You’re all set')+`<div class="screen-center"><div class="circle-icon">${icon('check')}</div><h2>${t('Welcome to Plus.')}</h2><p class="subtitle">${t('Your 7-day demo trial is now active.')}</p>${btn('Start my journey','finishOnboarding()')}</div>`;
// Health dashboard drilldowns
screens.wellness=()=>header('Daily wellness',ib('share',"share('Daily wellness')",'Share'))+tabs(['Day','Week','Month'],period,'setPeriod')+`<div class="screen-center" style="padding-top:0"><span class="pill">${t('Friday, 18 September')}</span><div class="hero-value">${82+Math.min(state.workouts.length*2,16)}<small> /100</small></div><span class="pill">${t('In balance')} · +8 ${t('pts')}</span><p class="subtitle">${t('A steady rhythm. You’re moving more and recovering well.')}</p></div><div class="card">${chart(period==='Day'?[54,58,61,68,72,80,82]:period==='Month'?[58,65,60,69,71,77,82]:undefined)}${row('How your score works','Movement, recovery and consistency','leaf',"go('scoreInfo')")}</div><div class="card mt">${row('Steps','6,248 / '+state.stepsGoal,'activity',"go('activity','Steps')")}${row('Active minutes',(32+state.workouts.reduce((a,b)=>a+b.minutes,0))+' min','clock',"go('activity','Active minutes')")}${row('Heart rate',(state.hearts[0]?.value||'—')+' bpm','heart',"go('history')")}${row('Edit daily goals','','settings',"go('goals')")}${row('Daily records','','plan',"go('calendar')")}</div>${healthNote()}`;
function setPeriod(p){period=p;render()}
screens.scoreInfo=()=>header('Your wellness score')+`<div class="card"><h2>${t('A snapshot, not a diagnosis.')}</h2><p class="subtitle">${t('This demo combines activity, recovery and consistency into an illustrative daily score. Trends are more useful than a single number.')}</p>${row('Movement','40% · Steps and active time','activity',"go('activity')")}${row('Recovery','35% · Resting heart rate and rest days','heart',"go('history')")}${row('Consistency','25% · Your regular healthy habits','plan',"go('streak')")}</div>${healthNote()}`;
screens.activity=()=>header(param||'Activity',ib('settings',"go('goals')",'Edit goals'))+tabs(['Day','Week','Month'],period,'setPeriod')+`<div class="screen-center" style="padding-top:0"><p class="muted">${t(param||'Steps')}</p><div class="hero-value">${param==='Calories'?energy(284):param==='Active minutes'?32+state.workouts.reduce((a,b)=>a+b.minutes,0):'6,248'}<small> ${param==='Calories'?energyUnit():param==='Active minutes'?t('min'):t('steps')}</small></div><span class="pill">${Math.round(6248/state.stepsGoal*100)}% ${t('of daily goal')}</span></div><div class="card mt">${chart(period==='Day'?[12,44,20,65,35,84,42]:period==='Month'?[52,68,77,56,79,88,95]:[52,68,79,60,91,58,78],true)}<div class="grid2"><div><span class="muted tiny">${t('Distance')}</span><h3>${state.unit==='metric'?'4.7 km':'2.9 mi'}</h3></div><div><span class="muted tiny">${t('Energy burned')}</span><h3>${energy(284)} ${energyUnit()}</h3></div></div></div><div class="card mt">${row('Edit daily goals','','settings',"go('goals')")}${row('Data sources & sync','Demo activity data','device',"go('devices')")}${row('History calendar','','plan',"go('calendar')")}</div>${healthNote()}`;
function energy(v){return state.unit==='metric'?v:Math.round(v*4.184)}const energyUnit=()=>state.unit==='metric'?'kcal':'kJ';
screens.goals=()=>header('Daily goals')+`<p class="subtitle">${t('Set targets that fit your everyday life.')}</p>`+field('Daily steps','steps',state.stepsGoal,'number','min="1000" max="50000" step="500"')+field('Active minutes','activeGoal',state.activeGoal||40,'number')+field('Energy goal (kcal)','energyGoal',state.energyGoal||400,'number')+`<div id="formerror" class="error"></div>`+btn('Save goals',"if(+val('steps')<1000||+val('steps')>50000||+val('activeGoal')<1||+val('energyGoal')<1){document.getElementById('formerror').textContent=t('Please enter realistic, positive goals.')}else{state.stepsGoal=+val('steps');state.activeGoal=+val('activeGoal');state.energyGoal=+val('energyGoal');save();back();toast('Goals updated')}");
screens.calendar=()=>header('Daily records')+`<h2>${t('September 2026')}</h2><div class="week">${['M','T','W','T','F','S','S'].map(x=>`<span style="text-align:center">${x}</span>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px">${Array.from({length:30},(_,i)=>`<button class="day ${i===17?'active':''}" onclick="go('dayRecord','${i+1} September')"><b>${i+1}</b>${i<18?'<span class="day-dot"></span>':''}</button>`).join('')}</div>`;
screens.dayRecord=()=>header(String(param))+`<div class="card"><h3>${t('Activity overview')}</h3>${chart([45,65,50,81,65,85,73],true)}<p>${t('Steps')}: 6,248 · ${t('Active minutes')}: 32</p></div>${healthNote()}`;
screens.streak=()=>header('Your consistent little wins')+`<div class="screen-center"><div class="circle-icon">${icon('flame')}</div><h2>7 ${t('days, one good habit.')}</h2><p class="subtitle">${t('You showed up for yourself. That matters.')}</p></div>`+screens.calendar().replace(header('Daily records'),'');
// Training detail, execution, rest and completion
const exercises=['Standing warm-up','Bodyweight squats','Reverse lunges','Forearm plank','Gentle cool-down'];
screens.workout=()=>header(param||'Full body flow',ib('bookmark',"favorite(param||'Full body flow')",'Save workout'))+`<div class="exercise-visual"><img src="${photo}" alt="Full body training"><span class="cover-label">${t('MOVE WITH INTENTION')}</span></div><h2 class="mt">${t(param||'Full body flow')}</h2><p class="subtitle">${t('A feel-good blend of strength and mobility. Move at your own pace and leave a little lighter.')}</p><div class="mini-stats card"><div><strong>${state.duration}</strong><small>${t('minutes')}</small></div><div><strong>5</strong><small>${t('movements')}</small></div><div><strong>${energy(145)}</strong><small>${energyUnit()}</small></div></div><div class="chip-row"><span class="pill">${t(state.experience)}</span><span class="pill">${t(state.equipment)}</span><span class="pill">${t('Full body')}</span></div>${section('Your movements')}<div class="card">${exercises.map((x,i)=>row(x,'3 × 30 sec','dumbbell',`go('exercise','${i}')`)).join('')}</div><p class="disclaimer">${t('Move within your comfort range. Stop if you feel pain or dizziness.')}</p>${btn('Start workout',"startWorkout()",'primary mt')}`;
screens.exercise=()=>{let i=+param||0;let tips=[['Stand tall with feet hip-width apart.','Roll your shoulders and march gently.','Keep breathing slowly and naturally.'],['Stand with your feet shoulder-width apart.','Send your hips back and bend your knees.','Press through your feet to stand tall.'],['Step one foot behind you.','Lower both knees with your torso upright.','Push through the front foot and switch sides.'],['Place elbows under your shoulders.','Keep a straight line from head to heels.','Breathe and gently brace your core.'],['Slow your breathing and relax your shoulders.','Stretch gently without bouncing.','Hold only within a comfortable range.']][i];return header(exercises[i],ib('bookmark',`favorite('${exercises[i]}')`,'Save movement'))+`<div class="exercise-visual"><img src="${photo}" alt="Workout cover — simulated demonstration"><button class="play-circle" onclick="toast('Demo cover — follow the movement instructions below')" aria-label="Play demo">${icon('play')}</button></div><p class="disclaimer">${t('Demo movement cover · no live video')}</p>${section('How to move')}<div class="stack">${tips.map((x,j)=>`<div class="row top"><span class="pill">0${j+1}</span><p>${t(x)}</p></div>`).join('')}</div>${section('Keep it comfortable')}<div class="card"><p>${t('Avoid rushing or holding your breath. Keep your joints softly aligned and reduce the range if needed.')}</p></div>${btn('Try an alternative',`go('exercise','${(i+1)%5}')`,'secondary mt')}${btn('Add to custom workout',`state.custom=state.custom||[];state.custom.push('${exercises[i]}');save();toast('Added to your custom workout')`,'secondary mt')}`};
function startWorkout(){workIndex=0;seconds=30;paused=false;rest=false;state.workoutDraft=null;go('player')}
screens.player=()=>header(rest?'Take a breath':'Your workout',ib('close','exitWorkout()','Exit workout'))+`<div class="bar"><span style="width:${workIndex/5*100}%"></span></div><p class="step-label">${t('MOVEMENT')} ${workIndex+1} / ${exercises.length} · ${t('SET')} 1 / 1</p><h2>${t(rest?'A moment to reset.':exercises[workIndex])}</h2><p class="subtitle">${t(rest?'Breathe in. Breathe out. You’re doing well.':'Focus on your form. Your pace is the right pace.')}</p>${rest?`<div class="circle-icon" style="animation:breathe 3s infinite">${icon('leaf')}</div>`:`<div class="exercise-visual"><img src="${photo}" alt="Simulated movement demonstration"><span class="cover-label">${t('DEMO MOVEMENT')}</span></div>`}<div class="screen-center" style="padding-top:0"><div class="timer" id="timer">00:${String(seconds).padStart(2,'0')}</div><p class="muted">${t(rest?'Rest time':'Time remaining')}</p></div><div class="row mt">${ib('back','previousExercise()','Previous movement')}${btn(rest?'Skip rest':paused?'Resume':'Pause',rest?'endRest()':'pauseWorkout()')}${ib('skip','nextExercise()','Next movement')}</div><p class="disclaimer">${t('Demo sessions are accelerated. You can skip to the next movement.')}</p>`;
function pauseWorkout(){paused=!paused;if(paused)sheet('Take your time.','Your progress is safe. Continue when you’re ready.',btn('Resume',"paused=false;closeSheet();render()")+btn('Save & exit','exitWorkout()','secondary'));render()}
function nextExercise(){if(rest){endRest();return}if(workIndex===4){go('complete');return}rest=true;seconds=10;paused=false;render()}
function endRest(){workIndex++;rest=false;seconds=30;render()}
function previousExercise(){workIndex=Math.max(0,workIndex-1);rest=false;seconds=30;render()}
function exitWorkout(){paused=true;sheet('Pause your progress?','Save this session to pick it up later, or discard it.',btn('Save & exit',"state.workoutDraft={index:workIndex,seconds,rest};save();closeSheet();nav('plan');toast('Progress saved')")+btn('Discard workout',"closeSheet();nav('home')",'secondary')+btn('Continue workout',"paused=false;closeSheet()",'text-button'))}
let feeling='Just right';
screens.complete=()=>header('A little stronger')+`<div class="screen-center" style="padding-top:0"><div class="circle-icon">${icon('check')}</div><h2 class="big-title">${t('You showed up.<br>That’s a win.')}</h2><p class="subtitle">${t('Full body flow, beautifully done.')}</p></div><div class="mini-stats card"><div><strong>${state.duration}</strong><small>${t('minutes')}</small></div><div><strong>${energy(145)}</strong><small>${energyUnit()}</small></div><div><strong>112</strong><small>${t('avg bpm')}</small></div></div><div class="card mt"><div class="row between"><span>${t('Movements completed')}</span><strong>5 / 5</strong></div><div class="bar mt"><span style="width:100%"></span></div></div>${section('How did that feel?')}<div class="row">${['Easy','Just right','Hard'].map(x=>btn(x,`feeling='${x}';render()`,feeling===x?'primary':'secondary')).join('')}</div>${btn('Save & finish','completeWorkout(false)','primary mt')}${btn('Share to Community','completeWorkout(true)','secondary mt')}${healthNote()}`;
function completeWorkout(community){state.workouts.unshift({id:Date.now(),name:'Full body flow',minutes:state.duration,calories:145,heart:112,date:new Date().toISOString(),feeling});state.workoutDraft=null;save();if(community){state.draft=t('A little stronger today. Finished my Full body flow — feeling great!');state.attachWorkout=true;go('compose')}else{nav('home');toast('Workout saved. Your daily progress is updated.')}}
// Heart rate simulated flow
screens.heart=()=>header('Heart rate',ib('clock',"go('history')",'History'))+`<div class="screen-center" style="padding-top:8px"><div class="circle-icon peach">${icon('heart')}</div><h2>${t('A moment to check in.')}</h2><p class="subtitle">${t('Sit comfortably, cover your camera gently with a fingertip and stay still.')}</p></div><div class="card">${row('Find a comfortable position','Rest for a moment before you begin','leaf',"toast('Sit with your feet supported and relax your shoulders')")}${row('Cover the camera','Use gentle, steady contact','camera',"toast('No real camera is used in this demo')")}${row('Stay still for 15 seconds','Breathe normally','clock',"toast('The demo runs a simulated 15-second measurement')")}</div>${btn('Start measurement','requestCamera()','primary mt')}${btn('View heart rate history',"go('history')",'secondary mt')}${healthNote()}`;
function requestCamera(){sheet('Camera permission','This demo simulates camera access. No camera or health data is actually collected.',btn('Allow demo measurement',"state.permissions.Camera=true;save();closeSheet();startMeasure()")+btn('Not now',"state.permissions.Camera=false;save();closeSheet();go('permissionDenied')",'secondary'))}
screens.permissionDenied=()=>header('Camera access')+`<div class="empty">${icon('camera')}<h3>${t('You’re in control.')}</h3><p>${t('Enable the simulated camera permission in Settings to try a measurement.')}</p></div>${btn('Open permission settings',"go('permissions')")}${btn('Try again','requestCamera()','secondary mt')}`;
function startMeasure(){measureProgress=0;measureIssue='';go('measuring')}
screens.measuring=()=>header('Checking your rhythm')+`<div class="screen-center"><div class="circle-icon peach" style="animation:breathe 1s infinite">${icon('heart')}</div><h2>${t('Breathe. Stay still.')}</h2><p class="subtitle">${t('Your moment of calm.')}</p><svg class="pulse-line" viewBox="0 0 300 100"><path d="M0 50h35l8-8 7 8h25l10-18 8 48 13-70 12 49 8-9h25l9-8 8 8h25l10-18 8 48 13-70 12 49 8-9h44"/></svg><div class="hero-value"><span id="measurecount">15</span><small> ${t('sec')}</small></div><p id="signal" class="muted">${t('Good signal · simulated')}</p><div class="bar mt"><span id="measurebar" style="width:0%"></span></div></div>${btn('Cancel','back()','secondary mt')}<details class="mt"><summary class="muted tiny">${t('Demo signal scenarios')}</summary><div class="stack mt">${['Finger not covering camera','Low light','Movement detected','Measurement failed'].map(x=>btn(x,`measureIssue='${x}';render()`,'secondary')).join('')}</div></details>${measureIssue?`<div class="card mt"><p>${t(measureIssue)}</p>${btn('Retry',"measureIssue='';measureProgress=0;render()",'primary mt')}</div>`:''}${healthNote()}`;
screens.heartResult=()=>header('Your heart rhythm')+`<div class="screen-center" style="padding-top:0"><span class="pill">${t('Simulated reading')}</span><div class="hero-value">${state.pendingHeart||72}<small> bpm</small></div><span class="pill">${t('At ease')}</span><p class="subtitle">${t('A moment in your day, not the whole picture.')}</p></div>`+select('How were you feeling?','hrcontext',['Resting','After workout','Stressed'],'Resting')+field('Add a note','hrnote','')+btn('Save reading',"saveHeart()")+btn('Measure again','startMeasure()','secondary mt')+healthNote();
function saveHeart(){state.hearts.unshift({id:Date.now(),value:state.pendingHeart||72,context:val('hrcontext'),note:val('hrnote'),date:new Date().toISOString()});save();go('history');toast('Reading saved')}
screens.history=()=>header('Heart rate history',ib('plus',"go('heart')",'New measurement'))+tabs(['Day','Week','Month'],period,'setPeriod')+(state.hearts.length?`<div class="card"><span class="muted">${t('Average resting heart rate')}</span><div class="metric-number">${Math.round(state.hearts.reduce((a,b)=>a+b.value,0)/state.hearts.length)} <small>bpm</small></div>${chart(period==='Day'?[68,72,70,73,69,71,72]:period==='Month'?[75,73,74,70,71,68,70]:[73,72,76,69,70,68,72])}<div class="row between"><small>${t('Lowest')}: ${Math.min(...state.hearts.map(h=>h.value))} bpm</small><small>${t('Highest')}: ${Math.max(...state.hearts.map(h=>h.value))} bpm</small></div></div>${section('Your readings')}<div class="card">${state.hearts.map(h=>row(`${h.value} bpm`,`${formatRecordDate(h.date,true)} · ${t(h.context)}`,'heart',`go('heartRecord','${h.id}')`)).join('')}</div>`:`<div class="empty">${icon('heart')}<h3>${t('Your first reading starts here.')}</h3>${btn('Measure now',"go('heart')",'primary mt')}</div>`)+healthNote();
screens.heartRecord=()=>{let h=state.hearts.find(h=>h.id==param);return header('Reading details')+(h?`<div class="screen-center"><div class="hero-value">${h.value}<small> bpm</small></div><p>${formatRecordDate(h.date,true)} · ${t(h.context)}</p><p class="subtitle">${esc(h.note)||t('No note added.')}</p></div>${btn('Share reading',"share('Heart rate reading')")}${btn('Delete reading',`confirmAction('Delete reading?',"state.hearts=state.hearts.filter(x=>x.id!=${h.id});save();back();toast('Reading deleted')")`,'secondary danger mt')}${healthNote()}`:`<div class="empty">${t('This record has been deleted.')}</div>`)};
// Body records
screens.body=()=>header('Body & progress',ib('plus',"go('addBody')",'Add record'))+`<div class="screen-center" style="padding-top:0"><p class="muted">${t('Your latest weight')}</p><div class="hero-value">${weight(state.weight)}<small> ${state.unit==='metric'?'kg':'lb'}</small></div><span class="pill">${t('Target')} ${weight(state.target)} ${state.unit==='metric'?'kg':'lb'}</span></div><div class="card mt">${chart(state.weights.length>1?state.weights.slice(0,7).reverse().map(x=>x.value):[74,73.8,73.5,73.6,73.1,72.8,state.weight])}<div class="grid2"><div><p class="muted tiny">BMI</p><h3>${(state.weight/(state.height/100)**2).toFixed(1)}</h3></div><div><p class="muted tiny">${t('Body fat')}</p><h3>${state.weights[0]?.fat||'—'} %</h3></div></div></div>${btn('Add body record',"go('addBody')",'primary mt')}${section('Your records')}<div class="card">${state.weights.map(w=>row(`${weight(w.value)} ${state.unit==='metric'?'kg':'lb'}`,w.date,'weight',`go('bodyRecord','${w.id}')`)).join('')||`<p class="muted">${t('No records yet.')}</p>`}${row('Edit target weight','','settings',"go('targetWeight')")}</div>${healthNote()}`;
screens.addBody=()=>header('A small check-in')+`<p class="subtitle">${t('Add what you know. Every body has its own pace.')}</p>`+field(state.unit==='metric'?'Weight (kg)':'Weight (lb)','newweight','','number','step="0.1"')+field('Body fat (%)','fat','','number','step="0.1"')+`<div class="grid2">${field('Waist (cm)','waist','','number')}${field('Hip (cm)','hip','','number')}</div>`+field('Chest (cm)','chest','','number')+`<p id="formerror" class="error"></p>`+btn('Save record','saveBody()');
function saveBody(){let w=+val('newweight');if(state.unit!=='metric')w/=2.20462;if(!w&&!val('fat')&&!val('waist')&&!val('hip')&&!val('chest')){document.getElementById('formerror').textContent=t('Add at least one measurement.');return}if((w&&(w<30||w>300))||(+val('fat')&&( +val('fat')<2||+val('fat')>70))){document.getElementById('formerror').textContent=t('Please check your measurements.');return}state.weights.unshift({id:Date.now(),value:w||state.weight,fat:val('fat'),waist:val('waist'),hip:val('hip'),chest:val('chest'),date:new Date().toISOString()});if(w)state.weight=w;save();back();toast('Body record saved')}
screens.bodyRecord=()=>{let w=state.weights.find(w=>w.id==param);return header('Body record')+(w?`<div class="card"><span class="muted">${formatRecordDate(w.date)}</span><div class="hero-value">${weight(w.value)}<small>${state.unit==='metric'?'kg':'lb'}</small></div><p>${t('Body fat')}: ${w.fat||'—'}%<br>${t('Waist')}: ${w.waist||'—'} cm<br>${t('Hip')}: ${w.hip||'—'} cm<br>${t('Chest')}: ${w.chest||'—'} cm</p></div>${btn('Delete record',`confirmAction('Delete body record?',"state.weights=state.weights.filter(x=>x.id!=${w.id});state.weight=state.weights[0]?.value||state.weight;save();back();toast('Record deleted')")`,'secondary danger mt')}`:`<p>${t('This record has been deleted.')}</p>`)};
screens.targetWeight=()=>header('Your target')+field(state.unit==='metric'?'Target weight (kg)':'Target weight (lb)','targetweight',(state.unit==='metric'?state.target:state.target*2.20462).toFixed(1),'number','step="0.1"')+btn('Save',"let w=+val('targetweight')/(state.unit==='metric'?1:2.20462);if(w<30||w>300)toast('Please check your measurements.');else{state.target=w;save();back();toast('Target updated')}");
// Plans and content libraries
function weekCalendar(){return `<div class="week">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<button class="day ${selectedDay===i?'active':''}" onclick="selectedDay=${i};go('dayPlan','${i}')"><span>${t(d)}</span><b>${14+i}</b><span class="day-dot" style="opacity:${i%3===1?.2:1}"></span></button>`).join('')}</div>`}
screens.plan=()=>`<div class="row between"><div><span class="greeting">${t('ONE DAY AT A TIME')}</span><h2>${t('Your plan')}</h2></div>${ib('settings',"go('planSettings')",'Plan settings')}</div><div class="plan-hero mt"><div class="row between"><span class="eyebrow">${t('WEEK 2 OF 4')}</span><span class="pill" style="background:#ffffff1c">${t(state.planStatus==='active'?'On track':'Paused')}</span></div><h2 style="margin-top:16px">${t('Build your balance')}</h2><p>${t(state.goal)} · ${state.frequency} ${t('days a week')}</p><div class="row between tiny" style="margin-bottom:9px"><span>${t('This week')}</span><span>${Math.min(state.workouts.length,state.frequency)} / ${state.frequency} ${t('sessions')}</span></div><div class="bar"><span style="width:${Math.min(state.workouts.length/state.frequency*100,100)}%"></span></div></div>${weekCalendar()}${section('Today, at your pace','Full plan',"go('fullPlan')")}${state.workoutDraft?`<div class="card mint mb"><h3>${t('Pick up where you left off')}</h3>${btn('Resume workout',"workIndex=state.workoutDraft.index;seconds=state.workoutDraft.seconds;rest=state.workoutDraft.rest;paused=false;go('player')",'primary mt')}</div>`:''}<div class="card">${row('Full body flow',state.duration+' '+t('min')+' · '+t(state.experience),'dumbbell',"go('workout','Full body flow')")}${row('Evening wind-down','10 min · Mobility','leaf',"go('workout','Evening wind-down')")}${row('Hydration check-in','A little water, a little reset','activity',"go('task','Hydration check-in')")}</div><div class="row mt">${btn('Adjust plan',"go('adjust')",'secondary')}${btn('Weekly review',"go('review')",'secondary')}</div>${section('Find your next favourite')}<div class="grid2"><button class="card card-button mint" onclick="go('library')">${icon('dumbbell')}<h3 class="mt">${t('Workout library')}</h3><p class="muted tiny mt">${t('Move your way')} ↗</p></button><button class="card card-button blue" onclick="go('movements')">${icon('activity')}<h3 class="mt">${t('Movement library')}</h3><p class="muted tiny mt">${t('Build your confidence')} ↗</p></button></div>`;
screens.dayPlan=()=>header(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][+param||0]||'Your day')+`<span class="pill">${14+(+param||0)} ${t('September')}</span><h2 class="mt">${t([1,5].includes(+param)?'Rest is part of progress.':'A little movement. A better day.')}</h2><p class="subtitle">${t('Your balanced daily routine.')}</p><div class="card">${([1,5].includes(+param)?['Mindful walk','Gentle stretch','Hydration check-in']:['Standing warm-up','Full body flow','Gentle cool-down','Hydration check-in','Heart rate check-in']).map(x=>row(x,state.tasks?.[x]?'Completed':'Planned','check',`go('task','${x}')`)).join('')}</div>`;
screens.task=()=>header(param)+`<div class="circle-icon">${icon('leaf')}</div><h2>${t(param)}</h2><p class="subtitle">${t('Make a little space for yourself today.')}</p>${field('Reminder time','tasktime',state.taskTimes?.[param]||'18:00','time')}${btn('Save time',"state.taskTimes={...state.taskTimes,[param]:val('tasktime')};save();toast('Reminder updated')",'secondary')}${btn('Mark complete',"state.tasks={...state.tasks,[param]:true};save();back();toast('Task completed')",'primary mt')}${btn('Start activity',"if(param.includes('Heart'))go('heart');else go('workout',param)",'secondary mt')}${btn('Replace task',"go('library')",'text-button')}${btn('Skip today',"state.tasks={...state.tasks,[param]:'skipped'};save();back();toast('Task skipped for today')",'text-button')}`;
screens.fullPlan=()=>header('Your complete plan',ib('settings',"go('adjust')",'Adjust plan'))+tabs(['Week','Month'],period==='Day'?'Week':period,'setPeriod')+`<div class="plan-hero"><span class="eyebrow">${t('4 WEEKS · YOUR OWN PACE')}</span><h2 class="mt">${t('Build your balance')}</h2><p>${t(state.goal)} · ${state.frequency} ${t('days per week')} · ${state.duration} ${t('min')}</p></div>${[1,2,3,4].map(n=>`<div class="card mt">${row('Week '+n,n===1?'Foundations':n===2?'Find your rhythm':n===3?'Build consistency':'Feel your progress','plan',`go('weekDetail','${n}')`)}<div class="bar"><span style="width:${n===1?100:n===2?50:0}%"></span></div></div>`).join('')}${btn('Adjust this plan',"go('adjust')",'primary mt')}${btn('Create a new plan',"flowMode='newplan';draftAnswers={...state};onboardStep=0;go('onboarding')",'secondary mt')}`;
screens.weekDetail=()=>header('Week '+param)+`<div class="card"><h3>${t('Your focus: consistency')}</h3><p class="subtitle">${t('Alternate movement and recovery. Small, regular sessions are the goal.')}</p></div>${weekCalendar()}${btn('View daily routine',"go('dayPlan','4')")}${btn('Plan stages',"go('planStages')",'secondary mt')}`;
screens.planStages=()=>header('Your plan stages')+`<div class="card">${['Week 1 · Learn the movements','Week 2 · Find your rhythm','Week 3 · Build consistency','Week 4 · Reflect and progress'].map(x=>`<p style="padding:18px 0;border-bottom:1px solid var(--line)">${t(x)}</p>`).join('')}</div><p class="subtitle">${t('Your plan adapts to your choices. Progress is personal and is not guaranteed.')}</p>`;
screens.adjust=()=>header('Make it fit you')+`<p class="subtitle">${t('Your plan should fit your life, not the other way around.')}</p>`+select('Your goal','planGoal',goals,state.goal)+select('Days per week','frequency',['2','3','4','5','6'],String(state.frequency))+select('Minutes per session','duration',['10','20','30','45','60'],String(state.duration))+select('Difficulty','difficulty',['Beginner','Intermediate','Advanced'],state.experience)+select('Movement focus','focus',['Strength & mobility','Yoga','Running','HIIT'],state.movement||'Strength & mobility')+select('Extra rest day','restday',['None','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],state.restday||'None')+btn('Update my plan','adjustPlan()');
function adjustPlan(){const changed={goal:val('planGoal'),frequency:+val('frequency'),duration:+val('duration'),experience:val('difficulty'),movement:val('focus'),restday:val('restday')};window.planChange=changed;sheet('Your updated rhythm',`${changed.frequency} ${t('days per week')} · ${changed.duration} ${t('min')} · ${t(changed.experience)}`,btn('Confirm changes',"Object.assign(state,window.planChange);save();closeSheet();nav('plan');toast('Your new plan is ready')")+btn('Keep editing','closeSheet()','secondary'))}
screens.planSettings=()=>header('Plan settings')+`<div class="card">${row('Adjust current plan','','settings',"go('adjust')")}${row(state.planStatus==='paused'?'Resume plan':'Pause plan','','pause',"state.planStatus=state.planStatus==='paused'?'active':'paused';save();render();toast('Plan updated')")}${row('Restart plan','','activity',"confirmAction('Restart your plan?',\"state.planStatus='active';state.tasks={};save();render();toast('Plan restarted')\")")}${row('Delete plan','','trash',"confirmAction('Delete current plan?',\"state.planStatus='deleted';save();nav('plan');toast('Plan deleted. Create a new plan to begin again.')\")")}</div>${btn('Create a new plan',"flowMode='newplan';draftAnswers={...state};onboardStep=0;go('onboarding')",'primary mt')}`;
const courses=[{name:'Full body flow',type:'Strength',time:20},{name:'Morning mobility',type:'Mobility',time:10},{name:'Evening wind-down',type:'Yoga',time:15},{name:'Energising core',type:'Strength',time:20},{name:'Fresh air intervals',type:'Cardio',time:30}];
screens.library=()=>header('Workout library',ib('settings',"libraryFilters()",'Filters'))+`<input id="coursequery" aria-label="${t('Search workouts')}" placeholder="${t('Search workouts')}" oninput="filterCourses(this.value)"><div class="chip-row">${['All','Strength','Mobility','Yoga','Cardio','Saved'].map(x=>btn(x,`filter='${x}';render()`,filter===x?'chip active':'chip')).join('')}</div><div id="course-results">${courseResults('')}</div>`;
function courseResults(q){const items=courses.filter(c=>(filter==='All'||c.type===filter||(filter==='Saved'&&state.favorites.includes(c.name)))&&t(c.name).toLowerCase().includes(q.toLowerCase())&&(!state.libraryMax||c.time<=state.libraryMax));return items.map(c=>`<button class="card card-button mb" onclick="go('workout','${c.name}')"><div style="height:125px;overflow:hidden;border-radius:13px;margin-bottom:13px"><img src="${courseCover(c.name)}" alt="${t(c.name)}" style="width:100%;height:100%;object-fit:cover;object-position:center ${c.time===10?'25':'50'}%"></div><div class="row between"><h3>${t(c.name)}</h3>${icon('arrow')}</div><p class="muted tiny mt">${c.time} ${t('min')} · ${t(c.type)} · ${t('Beginner')}</p></button>`).join('')||`<div class="empty">${icon('search')}<h3>${t('No workouts found')}</h3><p>${t('Try another search or change your filters.')}</p></div>`}
function filterCourses(q){document.getElementById('course-results').innerHTML=courseResults(q)}
function libraryFilters(){sheet('Find your flow','Choose your preferred session length.',select('Maximum duration','maxduration',['10','20','30','45','60'],String(state.libraryMax||60))+select('Equipment','libequipment',['Bodyweight','Dumbbells','Full gym'],state.equipment)+btn('Apply filters',"state.libraryMax=+val('maxduration');state.equipment=val('libequipment');save();closeSheet();render()"))}
screens.movements=()=>header('Movement library')+`<input aria-label="${t('Search movements')}" placeholder="${t('Search movements')}" oninput="document.querySelectorAll('[data-movement]').forEach(x=>x.hidden=!x.dataset.movement.toLowerCase().includes(this.value.toLowerCase()))"><div class="card mt">${exercises.map((x,i)=>`<div data-movement="${t(x)}">${row(x,'Bodyweight · Beginner','dumbbell',`go('exercise','${i}')`)}</div>`).join('')}</div>`;
screens.review=()=>header('A week of little wins',ib('share',"share('Weekly review')",'Share'))+`<div class="plan-hero"><span class="eyebrow">${t('YOUR WEEKLY REVIEW')}</span><h2 class="mt">${t('Consistency looks good on you.')}</h2><p>${t('You made time for your wellbeing. Keep that rhythm going.')}</p></div><div class="mini-stats card mt"><div><strong>${state.workouts.length}</strong><small>${t('sessions')}</small></div><div><strong>${state.workouts.reduce((a,b)=>a+b.minutes,0)}</strong><small>${t('minutes')}</small></div><div><strong>${energy(state.workouts.reduce((a,b)=>a+b.calories,0))}</strong><small>${energyUnit()}</small></div></div>${chart([30,50,40,60,80,55,90],true)}<div class="card"><h3>${t('Next week, a gentler balance.')}</h3><p class="subtitle">${t('Add one mobility session and keep a recovery day between strength sessions.')}</p>${btn('Apply next week’s suggestion',"state.movement='Strength & mobility';state.restday='Wednesday';save();toast('Next week’s plan updated');nav('plan')")}${btn('Customise adjustment',"go('adjust')",'secondary mt')}${btn('Keep my current plan',"nav('plan')",'text-button')}</div>`;
const articles=[['Recovery','Rest is part of getting stronger.'],['Nutrition','A balanced plate, without the rules.'],['Sleep','Make room for better rest.'],['Heart health','Get to know your resting rhythm.'],['Stress','A two-minute pause for your day.']];
screens.insights=()=>header('A little perspective')+`<button class="card card-button mint" onclick="go('report')"><span class="eyebrow">${t('YOUR WEEK IN REVIEW')}</span><h2 class="mt">${t('Small steps. Real progress.')}</h2><p class="subtitle">${t('Your weekly health report is ready.')}</p>${icon('arrow')}</button><div class="chip-row">${['All','Recovery','Nutrition','Sleep','Heart health','Stress'].map(x=>btn(x,`filter='${x}';render()`,filter===x?'chip active':'chip')).join('')}</div><div class="card">${articles.filter(a=>filter==='All'||a[0]===filter||!['Recovery','Nutrition','Sleep','Heart health','Stress'].includes(filter)).map(([cat,title])=>row(title,cat+' · 3 min read','leaf',`go('article','${articles.findIndex(a=>a[1]===title)}')`)).join('')}</div>`;
screens.article=()=>{let a=articles[+param||0];return header(a[0],ib('bookmark',`favorite('${a[1]}')`,'Save article'))+`<span class="pill">${t(a[0])} · 3 ${t('min read')}</span><h2 class="big-title mt">${t(a[1])}</h2><p class="subtitle">${t('PulseFit journal · 18 September 2026')}</p><div class="card"><h3>${t('Give yourself a little space.')}</h3><p class="mt">${t('Wellbeing is built in ordinary moments. A walk outside, a pause between tasks, a regular bedtime — small choices can help you notice what feels good for you.')}</p><h3 class="mt">${t('Start with one small habit.')}</h3><p class="mt">${t('Choose something manageable and make room for it in your day. Notice how you feel over time, and adapt your routine to your own energy and circumstances.')}</p><h3 class="mt">${t('Listen to your body.')}</h3><p class="mt">${t('There is no perfect routine. Rest when you need to, and speak with a qualified professional if you have health concerns.')}</p></div>${btn('Share article',"share('PulseFit journal')",'secondary mt')}${btn('Related reading',`go('article','${((+param||0)+1)%articles.length}')`,'text-button')}${healthNote()}`};
screens.report=()=>header('Your weekly health report',ib('share',"share('Weekly health report')",'Share'))+`<span class="pill">14–20 ${t('September')}</span><h2 class="big-title mt">${t('Small steps.<br>Real progress.')}</h2><p class="subtitle">${t('Here’s how your healthy rhythm is taking shape.')}</p><div class="grid2"><div class="card mint"><p class="muted tiny">${t('Workouts')}</p><div class="metric-number">${state.workouts.length}</div></div><div class="card blue"><p class="muted tiny">${t('Activity goal')}</p><div class="metric-number">78<small>%</small></div></div><div class="card"><p class="muted tiny">${t('Resting heart rate')}</p><div class="metric-number">${state.hearts[0]?.value||'—'}<small> bpm</small></div></div><div class="card"><p class="muted tiny">${t('Current weight')}</p><div class="metric-number">${weight(state.weight)}<small> ${state.unit==='metric'?'kg':'lb'}</small></div></div></div><div class="card mt">${chart([45,65,73,58,82,78,86],true)}<h3>${t('Your best day: Friday')}</h3><p class="subtitle">${t('A balanced mix of movement and time to recharge.')}</p></div>${btn('See next week’s suggestion',"go('review')",'primary mt')}${healthNote()}`;
// Community: feed, posts, comments, challenges, topics
const seededPosts=[{id:'s1',name:'Sofia Laurent',initials:'SL',location:'Amsterdam, NL',text:'A slower morning, a clearer mind. 5 km by the water and absolutely no rush. Who else is making space for a little movement today?',image:true,topic:'EverydayMovement',likes:128,time:'2 hours ago'},{id:'s2',name:'Oliver Berg',initials:'OB',location:'Copenhagen, DK',text:'Day 5 of the morning stretch challenge. Just 10 minutes, but my mornings feel completely different.',image:false,topic:'SmallSteps',likes:86,time:'4 hours ago'}];
function allPosts(){return [...state.posts,...seededPosts].filter(p=>!state.blocked?.includes(p.name))}
function postCard(p,detail=false){return `<article class="card post"><div class="row between"><button class="row" style="background:none;text-align:left;padding:0" onclick="go('user','${p.id}')"><span class="avatar" style="background:${p.id==='s1'?'#e3ddd5':'#dae5d2'}">${esc(p.initials||'AM')}</span><span><strong style="font-size:13px">${esc(p.name)}</strong><small class="muted" style="display:block;margin-top:4px;font-size:12px">${esc(p.location||'Your community')} · ${t(p.time||'Just now')}</small></span></button>${ib('more',`postMenu('${p.id}')`,'More')}</div><${detail?'div':'button'} style="background:none;width:100%;text-align:left;padding:0" ${detail?'':`onclick="go('post','${p.id}')"`}><p>${t(esc(p.text))}</p>${p.image?`<img class="post-image" src="${p.image===true?runPhoto:esc(p.image)}" alt="Community members enjoying outdoor movement">`:p.workout?`<div class="card mint mt"><span class="eyebrow">${t('WORKOUT COMPLETE')}</span><h3 class="mt">${t('Full body flow')}</h3><p>20 ${t('min')} · ${energy(145)} ${energyUnit()}</p></div>`:''}</${detail?'div':'button'}><button class="text-button tag" onclick="go('topic','${esc(p.topic||'SmallSteps')}')">#${esc(p.topic||'SmallSteps')}</button><div class="post-actions"><button class="${state.likes[p.id]?'active':''}" onclick="like('${p.id}')" aria-label="${t('Like post')}">${icon('heart')} ${(p.likes||0)+(state.likes[p.id]?1:0)}</button><button onclick="go('post','${p.id}')" aria-label="${t('Comments')}">${icon('message')} ${(state.comments[p.id]||[]).length+(p.id==='s1'?12:0)}</button><button onclick="share('Community post')" aria-label="${t('Share')}">${icon('share')}</button><button style="margin-left:auto" onclick="favorite('post:${p.id}')" aria-label="${t('Save post')}">${icon(state.favorites.includes('post:'+p.id)?'check':'bookmark')}</button></div></article>`}
screens.community=()=>`<div class="row between"><div><span class="greeting">${t('BETTER, TOGETHER')}</span><h2>${t('Your kind of people')}</h2></div>${ib('search',"go('search')",'Search')}</div>${tabs(['For You','Following','Challenges'],communityTab,'changeCommunity')}${communityTab==='Challenges'?challengeList():`${communityTab==='For You'?`<button class="challenge-hero card-button" onclick="go('challenge')"><span class="eyebrow">${t('A LITTLE EVERY DAY')}</span><h3>${t('7 days.<br>A stronger you.')}</h3><p class="tiny">${t('Join 1,248 people finding their rhythm')}</p>${icon('trophy','big')}<span class="pill mt" style="background:#5968f2;color:#fff">${t(state.joined?'Check your progress':'Explore challenge')} ↗</span></button>`:''}<div class="section-head"><h3>${t(communityTab==='Following'?'From your people':'Good energy, shared')}</h3>${btn('New post',"go('compose')",'text-button')}</div>${allPosts().filter(p=>communityTab!=='Following'||state.following.includes(p.name)||p.name===state.name).map(p=>postCard(p)).join('')||`<div class="empty">${icon('community')}<h3>${t('Find your people')}</h3><p>${t('Follow someone from For You to see their updates here.')}</p>${btn('Explore the community',"communityTab='For You';render()",'primary mt')}</div>`}${btn('Explore topics',"go('topics')",'secondary mt')}`}`;
function changeCommunity(tab){communityTab=tab;render()}
function like(id){state.likes[id]=!state.likes[id];save();let y=document.getElementById('app').scrollTop;render();document.getElementById('app').scrollTop=y}
function favorite(id){if(state.favorites.includes(id)){state.favorites=state.favorites.filter(x=>x!==id);toast('Removed from saved')}else{state.favorites.push(id);toast('Saved to your favourites')}save();if(['favorites','post','community'].includes(page)){let y=document.getElementById('app').scrollTop;render();document.getElementById('app').scrollTop=y}}
screens.post=()=>{let p=allPosts().find(p=>p.id==param);return header('A shared moment')+(p?postCard(p,true)+section('Conversation')+`<div class="card">${(state.comments[p.id]||[]).map(c=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><strong>${esc(state.name)}</strong><p class="mt">${esc(c)}</p>${btn('Reply',"document.getElementById('comment').focus()",'text-button')}</div>`).join('')||`<p class="muted">${t('Start a kind conversation.')}</p>`}</div><label class="form-field"><span>${t('Your comment')}</span><input id="comment" placeholder="${t('Leave a little encouragement…')}"></label>${btn('Post comment','comment()')}`:`<div class="empty">${t('This content is no longer available.')}</div>`)};
function comment(){let c=val('comment').trim();if(!c){toast('Write something before posting');return}state.comments[param]=[...(state.comments[param]||[]),c];save();render();toast('Comment added')}
function postMenu(id){const p=allPosts().find(p=>p.id==id);sheet('Post options','Choose an action.',btn('Save post',`favorite('post:${id}');closeSheet()`,'secondary')+btn('Report post',`closeSheet();go('reportContent','${id}')`,'secondary')+btn('Block this person',`confirmAction('Block this person?',"state.blocked=[...(state.blocked||[]),allPosts().find(x=>x.id==='${id}').name];save();closeSheet();nav('community');toast('Person blocked')")`,'secondary')+(state.posts.some(p=>p.id==id)?btn('Delete post',`confirmAction('Delete this post?',"state.posts=state.posts.filter(x=>x.id!='${id}');save();nav('community')")`,'secondary danger'):''))}
screens.reportContent=()=>header('Report content')+`<p class="subtitle">${t('Help keep this a kind, supportive space.')}</p>`+select('Reason','reportreason',['Spam','Harassment','Misleading health advice','Inappropriate content'],'Spam')+field('Additional details','reportdetails','')+btn('Submit report',"back();toast('Report submitted. Thank you for helping our community.')");
screens.compose=()=>header('Share your little win',ib('close','back()','Close'))+select('Post type','posttype',['Workout check-in','Challenge progress','Achievement','Photo & text'],state.attachWorkout?'Workout check-in':'Photo & text')+`<label class="form-field"><span>${t('What’s your moment?')}</span><textarea id="posttext" placeholder="${t('A good workout, a small win, a fresh start…')}" oninput="document.getElementById('publish').disabled=!this.value.trim();state.draft=this.value;save()">${esc(state.draft)}</textarea></label><label class="form-field"><span>${t('Add a photo')}</span><input type="file" accept="image/*" id="upload" onchange="readPhoto(this)"></label><div id="uploadpreview"></div>`+field('Topic','posttopic','SmallSteps')+field('Location (optional)','postlocation','')+select('Who can see this?','visibility',['Everyone','Followers','Only me'],'Everyone')+`<label class="row mt"><input type="checkbox" id="attachworkout" ${state.attachWorkout?'checked':''}> ${t('Attach latest workout')}</label><button class="primary mt" id="publish" onclick="publishPost()" ${state.draft.trim()?'':'disabled'}>${t('Publish')}</button><p class="disclaimer">${t('Posts are saved only on this device. Nothing is sent publicly.')}</p>`;
let uploadImage='';function readPhoto(input){const file=input.files?.[0];if(!file)return;if(file.size>3e6){toast('Please choose an image smaller than 3 MB');input.value='';return}const reader=new FileReader();reader.onload=()=>{uploadImage=reader.result;document.getElementById('uploadpreview').innerHTML=`<img src="${uploadImage}" alt="Your selected photo" class="post-image">`};reader.readAsDataURL(file)}
function publishPost(){let text=val('posttext').trim();if(!text)return;const id='p'+Date.now();state.posts.unshift({id,name:state.name,initials:state.name.split(' ').map(x=>x[0]).join('').slice(0,2),text,topic:val('posttopic').replace('#','')||'SmallSteps',location:val('postlocation'),image:uploadImage||false,workout:document.getElementById('attachworkout').checked,visibility:val('visibility'),likes:0});state.draft='';state.attachWorkout=false;uploadImage='';try{save();go('published',id)}catch{state.posts.shift();toast('Device storage is full. Try a smaller photo.')}}
screens.published=()=>header('Moment shared')+`<div class="screen-center"><div class="circle-icon">${icon('check')}</div><h2>${t('Your good energy is out there.')}</h2><p class="subtitle">${t('Your post is now in your local demo feed.')}</p>${btn('View my post',"go('post',param)")}${btn('Back to Community',"communityTab='For You';nav('community')",'secondary mt')}</div>`;
function challengeList(){return `<div class="chip-row">${['All','Joined','Completed'].map(x=>btn(x,`filter='${x}';render()`,filter===x?'chip active':'chip')).join('')}</div>${(filter==='Joined'&&!state.joined)||(filter==='Completed'&&state.checkins<7)?`<div class="empty">${icon('trophy')}<h3>${t('Your next chapter awaits.')}</h3>${btn('Explore challenges',"filter='All';render()",'primary mt')}</div>`:`<button class="challenge-hero card-button" onclick="go('challenge')"><span class="eyebrow">${t(state.joined?'YOUR ACTIVE CHALLENGE':'MOVE TOGETHER')}</span><h3>${t('7 days.<br>A stronger you.')}</h3>${icon('trophy','big')}<p>1,248 ${t('participants')} · ${t('All levels')}</p><div class="bar mt" style="background:#c7de91"><span style="width:${state.checkins/7*100}%;background:var(--green)"></span></div><p class="tiny mt">${state.checkins} / 7 ${t('days completed')}</p></button>`}<div class="card mt">${row('30-day steps','A little further, every day','activity',"go('challenge','30-day steps')")}${row('Morning stretch','Start your day with space','leaf',"go('challenge','Morning stretch')")}${row('Heart health','Get to know your rhythm','heart',"go('challenge','Heart health')")}</div>`}
screens.challenge=()=>header(param||'7-day movement challenge',ib('share',"share('7-day movement challenge')",'Share'))+`<div class="challenge-hero"><span class="eyebrow">${t('LITTLE STEPS. TOGETHER.')}</span><h3>${t(param||'7 days.<br>A stronger you.')}</h3>${icon('trophy','big')}<p>18–24 ${t('September')} · 1,248 ${t('people')}</p></div><div class="mini-stats"><div><strong>7</strong><small>${t('days')}</small></div><div><strong>10</strong><small>${t('min / day')}</small></div><div><strong>1</strong><small>${t('new habit')}</small></div></div>${section('One small promise to yourself.')}<p class="subtitle">${t('Make time for at least 10 minutes of movement each day. Walk, stretch, dance — whatever feels good. Check in and cheer each other on.')}</p><div class="card">${row('Your reward','The Consistency badge + your certificate','trophy',"go('achievement','Consistency')")}${row('Community leaderboard','Celebrate showing up','community',"go('leaderboard')")}</div>${btn(state.joined?'Check my progress':'Join challenge',state.joined?"go('challengeProgress')":"state.joined=true;save();toast('You’re in. Let’s find your rhythm!');go('challengeProgress')",'primary mt')}`;
screens.challengeProgress=()=>header('Your little wins')+`<div class="circle-icon">${icon('trophy')}</div><h2 style="text-align:center">${state.checkins} ${t('of 7 days. Keep going.')}</h2><p class="subtitle" style="text-align:center">${t('Every check-in is a promise kept.')}</p><div class="bar"><span style="width:${state.checkins/7*100}%"></span></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:25px 0">${Array.from({length:7},(_,i)=>`<div class="card ${i<state.checkins?'mint':''}" style="padding:14px 7px;text-align:center">${icon(i<state.checkins?'check':'leaf')}<p class="tiny mt">${t('Day')} ${i+1}</p></div>`).join('')}</div>${btn(state.checkins>=7?'View my certificate':'Check in today',state.checkins>=7?"go('certificate')":"state.checkins++;save();render();toast('Another little win. Well done!')")}${btn('Community leaderboard',"go('leaderboard')",'secondary mt')}<p class="disclaimer">${t('Demo mode: each check-in advances one simulated day.')}</p>${btn('Leave challenge',"confirmAction('Leave this challenge?',\"state.joined=false;state.checkins=0;save();nav('community');toast('You left the challenge')\")",'text-button danger')}`;
screens.leaderboard=()=>header('Showing up, together')+`<p class="subtitle">${t('It’s about consistency, not competition.')}</p><div class="card">${[['Sofia Laurent',7],['Oliver Berg',6],[state.name,state.checkins],['Emma Wilson',4],['Luca Rossi',3]].sort((a,b)=>b[1]-a[1]).map(([n,score],i)=>`<div class="list-row"><span class="pill">${i+1}</span><span class="list-copy"><strong>${esc(n)}</strong><small>${score} / 7 ${t('check-ins')}</small></span>${score>=7?icon('trophy'):''}</div>`).join('')}</div>${state.checkins>=7?btn('View certificate',"go('certificate')",'primary mt'):btn('Keep your rhythm going',"go('challengeProgress')",'primary mt')}`;
screens.certificate=()=>header('Your achievement',ib('share',"share('Consistency certificate')",'Share'))+(state.checkins>=7?`<div class="card mint" style="text-align:center;padding:36px 22px;border:1px solid #d9ddff"><span class="eyebrow">PULSEFIT · CERTIFICATE</span><div class="circle-icon">${icon('trophy')}</div><h2 class="big-title">${t('The art of<br>showing up.')}</h2><p class="subtitle">${t('Awarded to')}</p><h2>${esc(state.name)}</h2><p class="subtitle">${t('For 7 days of intentional movement.<br>Small steps. A lasting rhythm.')}</p><div class="studio-line" style="margin:25px auto"></div><span class="tiny">${t('September 2026')} · PulseFit</span></div>${btn('Save certificate',"downloadCard('Consistency certificate')",'primary mt')}`:`<div class="empty">${t('Complete all 7 check-ins to unlock your certificate.')}</div>`);
screens.topics=()=>header('Find your conversation')+`<div class="card">${['SmallSteps','EverydayMovement','MorningRituals','MindfulRecovery','HeartHealth'].map(x=>row('#'+x,'A space for shared healthy habits','message',`go('topic','${x}')`)).join('')}</div>`;
screens.topic=()=>header('#'+param)+`<div class="card mint"><h2>#${esc(param)}</h2><p class="subtitle">${t('Small stories, shared encouragement. Join the conversation.')}</p>${btn((state.topics||[]).includes(param)?'Following topic':'Follow topic',"state.topics=state.topics||[];state.topics=state.topics.includes(param)?state.topics.filter(x=>x!==param):[...state.topics,param];save();render()")}</div>${allPosts().filter(p=>p.topic===param).map(p=>postCard(p)).join('')||`<div class="empty">${t('Be the first to share a moment here.')}</div>`}${btn('Share to this topic',"state.draft='#'+param+' ';save();go('compose')",'secondary mt')}`;
screens.user=()=>{let p=allPosts().find(x=>x.id==param)||seededPosts[0];return header('Community profile',ib('more',`postMenu('${p.id}')`,'More'))+`<div class="profile-head"><div class="avatar">${p.initials||'AM'}</div><h2>${esc(p.name)}</h2><p>${esc(p.location||'Your community')}</p><p>${t('Finding joy in the everyday. Movement, fresh air, good company.')}</p></div><div class="mini-stats"><div><strong>128</strong><small>${t('following')}</small></div><div><strong>842</strong><small>${t('followers')}</small></div><div><strong>46</strong><small>${t('workouts')}</small></div></div>${btn(state.following.includes(p.name)?'Following':'Follow',`follow('${p.id}')`)}${section('Shared moments')}${allPosts().filter(x=>x.name===p.name).map(x=>postCard(x)).join('')}`};
function follow(id){let p=allPosts().find(x=>x.id==id);state.following=state.following.includes(p.name)?state.following.filter(x=>x!==p.name):[...state.following,p.name];save();render()}
// Profile, settings and persistent preferences
screens.profile=()=>`<div class="row between"><h2>${t('Your space')}</h2>${ib('settings',"go('settings')",'Settings')}</div><div class="profile-head"><div class="avatar">${esc(state.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div><h2>${esc(state.name)}</h2><p>${t(state.goal)} · ${t('One day at a time')}</p><button class="pill" onclick="go('membership')">${icon('leaf')} ${t(state.member?'PulseFit Plus':'Free member')}</button><div>${btn('Edit profile',"go('editProfile')",'text-button')}</div></div><div class="card mini-stats"><div><strong>${state.workouts.length}</strong><small>${t('workouts')}</small></div><div><strong>${state.workouts.reduce((a,b)=>a+b.minutes,0)}</strong><small>${t('total minutes')}</small></div><div><strong>7</strong><small>${t('day streak')}</small></div></div><button class="card card-button mint mt" onclick="go('membership')"><div class="row between"><div><span class="eyebrow">PULSEFIT PLUS</span><h3 class="mt">${t(state.member?'More support, every day.':'A little more, just for you.')}</h3><p class="muted tiny mt">${t(state.member?'Manage your membership':'Explore your 7-day free trial')}</p></div>${icon('arrow')}</div></button><div class="card mt">${[['Health profile','heart','healthProfile'],['My data','activity','data'],['Training history','clock','trainingHistory'],['Achievements','trophy','achievements'],['Favourites','bookmark','favorites']].map(([s,i,p])=>row(s,'',i,`go('${p}')`)).join('')}</div><div class="card mt">${[['Membership','leaf','membership'],['Connected devices','device','devices'],['Settings','settings','settings'],['Privacy & permissions','shield','permissions'],['Help & support','message','help']].map(([s,i,p])=>row(s,'',i,`go('${p}')`)).join('')}</div><p class="disclaimer">PulseFit 1.0 · ${t('Made for your everyday')}</p>`;
screens.editProfile=()=>header('A little about you')+field('Full name','profilename',state.name)+field('Bio','bio',state.bio||'Finding my healthy rhythm.')+select('Gender','gender',['Prefer not to say','Woman','Man','Non-binary'],state.gender||'Prefer not to say')+field('Birthday','birthday',state.birthday||'1998-05-14','date')+select('Country / region','country',['Netherlands','Germany','France','Spain','United Kingdom','China','Japan'],state.country||'Netherlands')+btn('Save profile',"if(!val('profilename').trim())toast('Please enter your name');else{Object.assign(state,{name:val('profilename').trim(),bio:val('bio'),gender:val('gender'),birthday:val('birthday'),country:val('country')});save();back();toast('Profile updated')}");
screens.healthProfile=()=>header('Health profile',ib('edit',"flowMode='edit';draftAnswers={...state};onboardStep=1;go('onboarding')",'Edit health profile'))+`<div class="card">${[['Height',state.unit==='metric'?state.height+' cm':(state.height/30.48).toFixed(2)+' ft'],['Weight',weight(state.weight)+' '+(state.unit==='metric'?'kg':'lb')],['Target weight',weight(state.target)+' '+(state.unit==='metric'?'kg':'lb')],['Experience',state.experience],['Weekly sessions',String(state.frequency)],['Health goal',state.goal],['Injuries or limitations',state.injury]].map(([a,b])=>`<div class="list-row"><span class="list-copy">${t(a)}</span><strong>${t(b)}</strong></div>`).join('')}</div>${btn('Edit health profile',"flowMode='edit';draftAnswers={...state};onboardStep=1;go('onboarding')",'primary mt')}${healthNote()}`;
screens.data=()=>header('Your health, in view',ib('download','exportData()','Export data'))+`<div class="card mint"><span class="eyebrow">${t('YOUR OVERVIEW')}</span><h2 class="mt">${t('Every small step counts.')}</h2>${chart([40,60,55,70,68,82,85])}</div><div class="card mt">${row('Workouts',`${state.workouts.length} ${t('new sessions')}`,'dumbbell',"go('trainingHistory')")}${row('Heart rate',`${state.hearts.length} ${t('readings')}`,'heart',"go('history')")}${row('Activity','6,248 steps today','activity',"go('activity')")}${row('Body & progress',weight(state.weight)+' '+(state.unit==='metric'?'kg':'lb'),'weight',"go('body')")}${row('Weekly report','','plan',"go('report')")}</div>${btn('Download my data','exportData()','secondary mt')}${healthNote()}`;
screens.trainingHistory=()=>header('Training history')+`<div class="row">${select('Type','historytype',['All workouts','Strength','Mobility'],'All workouts')}${field('Date','historydate','','date','onchange="filterHistory()"')}</div><div id="historylist">${historyList()}</div>`;
function historyList(date=''){return state.workouts.filter(w=>!date||w.date.slice(0,10)===date).map(w=>`<div class="card mb">${row(w.name,`${new Date(w.date).toLocaleDateString(PF_I18N.locale(state.lang))} · ${nf(w.minutes)} ${t('min')}`,'dumbbell',`go('workoutRecord','${w.id}')`)}</div>`).join('')||`<div class="empty">${icon('dumbbell')}<h3>${t('Your next chapter starts here.')}</h3><p>${t('Complete a workout to start your training history.')}</p>${btn('Find a workout',"go('library')",'primary mt')}</div>`}
function filterHistory(){document.getElementById('historylist').innerHTML=historyList(val('historydate'))}
screens.workoutRecord=()=>{const w=state.workouts.find(x=>x.id==param);return header('Your session')+(w?`<div class="circle-icon">${icon('check')}</div><h2>${t(w.name)}</h2><p class="subtitle">${new Date(w.date).toLocaleDateString(PF_I18N.locale(state.lang))} · ${t(w.feeling)}</p><div class="mini-stats card"><div><strong>${w.minutes}</strong><small>${t('minutes')}</small></div><div><strong>${energy(w.calories)}</strong><small>${energyUnit()}</small></div><div><strong>${w.heart}</strong><small>bpm</small></div></div>${btn('Do this workout again',"go('workout','Full body flow')",'primary mt')}${btn('Share result',"share('Workout result')",'secondary mt')}${btn('Delete workout',`confirmAction('Delete workout?',"state.workouts=state.workouts.filter(x=>x.id!=${w.id});save();back();toast('Workout deleted')")`,'text-button danger')}`:`<div class="empty">${t('This record has been deleted.')}</div>`)};
screens.achievements=()=>header('Little wins, collected')+`<p class="subtitle">${t('A reminder of the times you showed up for yourself.')}</p><div class="badge-grid">${['First step','7-day rhythm','Consistency','Early bird','10 workouts','Heart aware'].map((x,i)=>`<button onclick="go('achievement','${x}')" style="opacity:${i>2?.5:1}">${icon(i===1?'flame':'trophy')}<p>${t(x)}</p><small class="muted">${t(i>2?'Not yet unlocked':'Earned')}</small></button>`).join('')}</div>`;
screens.achievement=()=>header(param)+`<div class="screen-center"><div class="circle-icon">${icon('trophy')}</div><h2>${t(param)}</h2><p class="subtitle">${t(param==='Consistency'?'Show up for 7 days in a community challenge.':'Celebrate every step of your healthy rhythm.')}</p>${btn('Share achievement',"share('Achievement')")}</div>`;
screens.favorites=()=>header('Saved for you')+`<div class="chip-row">${['All','Workouts','Movements','Articles','Posts'].map(x=>btn(x,`filter='${x}';render()`,filter===x?'chip active':'chip')).join('')}</div><div class="card">${state.favorites.filter(f=>filter==='All'||filter==='Workouts'&&courses.some(c=>c.name===f)||filter==='Movements'&&exercises.includes(f)||filter==='Articles'&&articles.some(a=>a[1]===f)||filter==='Posts'&&f.startsWith('post:')||!['Workouts','Movements','Articles','Posts'].includes(filter)).map(f=>row(f.startsWith('post:')?'Community post':f,'Saved','bookmark',`openFavorite('${esc(f)}')`)).join('')||`<div class="empty">${icon('bookmark')}<h3>${t('Keep what inspires you.')}</h3><p>${t('Saved workouts, movements and stories will appear here.')}</p></div>`}</div>${btn('Clear browsing history',"confirmAction('Clear browsing history?',\"state.browsing=[];save();toast('Browsing history cleared')\")",'text-button')}`;
function openFavorite(f){if(f.startsWith('post:'))go('post',f.slice(5));else if(exercises.includes(f))go('exercise',String(exercises.indexOf(f)));else if(articles.some(a=>a[1]===f))go('article',String(articles.findIndex(a=>a[1]===f)));else go('workout',f)}
screens.membership=()=>header('Your membership')+`<div class="plan-hero"><span class="eyebrow">PULSEFIT ${state.member?'PLUS':'FREE'}</span><h2 class="mt">${t(state.member?'More support, every day.':'Find your next chapter.')}</h2><p>${t(state.member?'Your demo trial is active.':'A little extra support for your everyday rhythm.')}</p><span class="pill" style="color:#5968f2">${t(state.member?(state.subscription||'Yearly'):'Free plan')}</span></div><div class="card mt">${row('Your benefits','Personal plans · Unlimited workouts · Insights','leaf',"go('benefits')")}${row(state.member?'Manage subscription':'Compare plans','','plan',"go('paywall')")}${row('Restore purchase','','activity','restore()')}${row('Redeem a code','','trophy',"go('redeem')")}${row('Order history','','clock',"go('orders')")}</div>${state.member?btn('How to cancel',"go('cancelSubscription')",'text-button'):btn('Explore Plus',"go('paywall')",'primary mt')}<p class="disclaimer">${t('Demo membership. No real payment or renewal.')}</p>`;
screens.benefits=()=>header('A little more with Plus')+`<div class="card">${['Personal plans that grow with you','Unlimited workouts & programmes','Deeper health insights','Full workout and movement library'].map(x=>`<div class="list-row">${icon('check')}<span>${t(x)}</span></div>`).join('')}</div>${btn('Compare plans',"go('paywall')",'primary mt')}`;
screens.redeem=()=>header('A little gift')+`<p class="subtitle">${t('Use PULSE7 to try a demo Plus membership.')}</p>`+field('Redeem code','redeemcode','')+btn('Redeem',"if(val('redeemcode').toUpperCase()==='PULSE7'){state.member=true;state.subscription='Gift';save();back();toast('Your demo membership is active')}else toast('That code is not recognised. Try PULSE7.')");
screens.orders=()=>header('Order history')+(state.member?`<div class="card">${row('PulseFit Plus','Demo order · €0.00 charged','leaf',"go('order')")}</div>`:`<div class="empty">${t('No orders yet.')}</div>`);
screens.order=()=>header('Order details')+`<div class="card"><h3>PulseFit Plus</h3><p class="subtitle">${t('Demo order')} · PF-20260918<br>${t('Plan')}: ${t(state.subscription||'Yearly')}<br>${t('Paid')}: €0.00<br>${t('Status')}: ${t('Confirmed')}</p></div>`;
screens.cancelSubscription=()=>header('Manage your subscription')+`<div class="card"><h3>${t('You’re always in control.')}</h3><p class="subtitle">${t('In a live app, subscriptions are managed through the App Store or Google Play. This demo has no real billing.')}</p>${btn('End demo membership',"confirmAction('End demo membership?',\"state.member=false;save();back();toast('Demo membership ended')\")",'secondary')}</div>`;
screens.devices=()=>header('A connected rhythm')+`<p class="subtitle">${t('Bring your everyday activity into one place.')}</p><div class="card">${['Apple Health','Health Connect','Apple Watch','Fitbit','Garmin','Other devices'].map(x=>row(x,state.devices[x]?'Connected · demo sync':'Not connected',x.includes('Health')?'heart':'device',`go('device','${x}')`)).join('')}</div><p class="disclaimer">${t('Connections and sync are simulated. No external account is accessed.')}</p>`;
screens.device=()=>header(param)+`<div class="circle-icon">${icon('device')}</div><h2 style="text-align:center">${esc(param)}</h2><p class="subtitle" style="text-align:center">${t(state.devices[param]?'Connected · your demo data is up to date.':'Sync your movement, heart rate and everyday progress.')}</p>${state.devices[param]?btn('Sync now','syncDevice()')+btn('Disconnect',"confirmAction('Disconnect this device?',\"state.devices[param]=false;save();render();toast('Device disconnected')\")",'secondary danger mt'):btn('Connect device',"toast('Connecting…');setTimeout(()=>{state.devices[param]=true;save();render();toast('Device connected')},700)")}<details class="mt"><summary class="muted tiny">${t('Demo sync scenarios')}</summary>${btn('Simulate sync failure',"sheet('Sync paused','We couldn’t finish syncing your demo data. Please try again.',btn('Retry','closeSheet();syncDevice()')+btn('Re-authorise',\"state.devices[param]=true;save();closeSheet();toast('Permission updated')\",'secondary'))",'secondary mt')}</details>`;
function syncDevice(){toast('Syncing demo data…');setTimeout(()=>{state.lastSync=Date.now();save();toast('Everything is up to date')},850)}
screens.settings=()=>header('Make yourself at home')+`<span class="eyebrow">${t('YOUR ACCOUNT')}</span><div class="card mt">${row('Account & security',state.email,'shield',"go('account')")}</div>${section('Look & feel')}<div class="card">${row('Language',({en:'English',zh:'简体中文',es:'Español',de:'Deutsch',fr:'Français',ja:'日本語'})[state.lang],'globe',"go('language')")}${row('Region',state.country||'Netherlands','globe',"go('region')")}${row('Appearance',state.theme==='dark'?'Dark':'Light','sun',"go('appearance')")}${row('Text size',state.textSize||'Default','edit',"go('textSize')")}</div>${section('Your preferences')}<div class="card">${row('Units',state.unit==='metric'?'Metric · kg, cm, km':'Imperial · lb, ft, mi','weight',"go('units')")}${row('Notifications','Only what matters to you','bell',"go('notificationSettings')")}${row('Privacy & permissions','Your data, your choice','shield',"go('permissions')")}</div>${btn('Log out',"confirmAction('Log out?',\"state.loggedIn=false;save();go('welcome');toast('You are logged out')\")",'secondary mt')}`;
screens.language=()=>header('Language')+`<p class="subtitle">${t('Choose the language that feels like home.')}</p><div class="stack">${Object.entries({en:'English',zh:'简体中文',es:'Español',de:'Deutsch',fr:'Français',ja:'日本語'}).map(([code,label])=>option(label,({en:'English',zh:'简体中文',es:'Español',de:'Deutsch',fr:'Français',ja:'日本語'})[state.lang],`state.lang='${code}';save();render();toast('Language updated')`)).join('')}</div>${btn('Done','back()','primary mt')}`;
screens.units=()=>header('Your units')+`<p class="subtitle">${t('Your numbers, the way you know them.')}</p><div class="stack">${option('Metric',state.unit==='metric'?'Metric':'Imperial',"state.unit='metric';save();render()",'kg · cm · km · kcal')}${option('Imperial',state.unit==='imperial'?'Imperial':'Metric',"state.unit='imperial';save();render()",'lb · ft · mi · kJ')}</div>`+select('Date format','dateformat',['DD/MM/YYYY','MM/DD/YYYY','YYYY-MM-DD'],state.dateformat||'DD/MM/YYYY')+select('Time zone','timezone',['Europe/Amsterdam','Europe/Berlin','Europe/Paris','Europe/London','Asia/Shanghai','Asia/Tokyo'],state.timezone||'Europe/Amsterdam')+btn('Save preferences',"state.dateformat=val('dateformat');state.timezone=val('timezone');save();back();toast('Preferences updated')");
screens.appearance=()=>header('Appearance')+`<div class="stack">${['Light','Dark'].map(x=>option(x,state.theme==='dark'?'Dark':'Light',`state.theme='${x.toLowerCase()}';save();render()`)).join('')}</div>${btn('Done','back()','primary mt')}`;
screens.textSize=()=>header('Text size')+`<div class="stack">${['Default','Large'].map(x=>option(x,state.textSize||'Default',`state.textSize='${x}';save();render()`)).join('')}</div><p class="subtitle">${t('A little every day. Build a healthier rhythm.')}</p>${btn('Done','back()')}`;
screens.region=()=>header('Region')+select('Country / region','country',['Netherlands','Germany','France','Spain','United Kingdom','China','Japan'],state.country||'Netherlands')+btn('Save',"state.country=val('country');save();back();toast('Region updated')");
function switches(names,obj){return `<div class="card">${names.map(x=>`<div class="list-row"><span class="list-copy"><strong>${t(x)}</strong></span><button class="switch ${state[obj][x]?'on':''}" role="switch" aria-checked="${!!state[obj][x]}" aria-label="${t(x)}" onclick="state.${obj}['${x}']=!state.${obj}['${x}'];save();render()"></button></div>`).join('')}</div>`}
screens.notificationSettings=()=>header('Only what matters')+`<p class="subtitle">${t('A helpful nudge, on your terms.')}</p>`+switches(['Workout reminder','Daily goal','Weekly report','Heart rate reminder','Community interaction','Marketing messages'],'notifications');
screens.permissions=()=>header('Your data. Your choice.')+`<p class="subtitle">${t('You choose what you share. All permissions are simulated in this demo.')}</p>`+switches(['Apple Health / Health Connect','Camera','Notifications','Motion & Fitness'],'permissions')+select('Profile visibility','profilevisibility',['Everyone','Followers','Only me'],state.profilevisibility||'Everyone')+select('Activity visibility','activityvisibility',['Everyone','Followers','Only me'],state.activityvisibility||'Only me')+btn('Save privacy preferences',"state.profilevisibility=val('profilevisibility');state.activityvisibility=val('activityvisibility');save();toast('Privacy preferences saved')",'secondary')+`<div class="card mt">${row('Download my data','','download','exportData()')}${row('Delete my health data','','trash',"confirmAction('Delete all health data?',\"state.workouts=[];state.hearts=[];state.weights=[];save();render();toast('Health records deleted')\")")}${row('Privacy Policy','','shield',"go('legal','Privacy Policy')")}${row('Terms of Service','','shield',"go('legal','Terms of Service')")}</div>`;
screens.account=()=>header('Account & security')+field('Email','accountemail',state.email,'email')+btn('Update email',"if(/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(val('accountemail'))){state.email=val('accountemail');save();toast('Email updated')}else toast('Enter a valid email')",'secondary')+`<div class="card mt">${row('Change password','','shield',"go('reset')")}${row('Delete account','','trash',"confirmAction('Delete your demo account?',\"localStorage.removeItem('pulsefit-v1');location.hash='welcome';location.reload()\")")}</div>`;
screens.legal=()=>header(param||'Privacy Policy')+`<h2>${t(param||'Privacy Policy')}</h2><p class="subtitle">${t('Prototype notice · September 2026')}</p><div class="card"><h3>${t('This is an interactive demo.')}</h3><p class="mt">${t('All account, subscription and health features are simulated. There is no real authentication, payment, camera access or health-device connection.')}</p><h3 class="mt">${t('Your data stays on this device.')}</h3><p class="mt">${t('Preferences and records are saved in your browser’s local storage. You can download or delete them in Privacy & permissions. Photos you add stay in this browser.')}</p><h3 class="mt">${t('Designed for wellbeing.')}</h3><p class="mt">${t('Health information in this demo is illustrative and does not constitute a medical diagnosis. Do not use the simulated readings to make health decisions.')}</p><h3 class="mt">${t('No actual subscription.')}</h3><p class="mt">${t('Displayed prices and trials illustrate a purchase flow. No money is charged and no subscription renews.')}</p></div>`;
screens.help=()=>header('A little help')+`<h2>${t('How can we help?')}</h2><label class="form-field"><input aria-label="Search help" placeholder="${t('Search questions')}" oninput="document.querySelectorAll('[data-faq]').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(this.value.toLowerCase()))"></label><div class="card">${['How do I change my plan?','How are heart readings measured?','How do I cancel my membership?','Where is my data stored?'].map((q,i)=>`<details data-faq style="padding:16px 0;border-bottom:1px solid var(--line)"><summary>${t(q)}</summary><p class="muted mt">${t(['Go to Plan → Adjust plan. Choose your days, duration and difficulty, then confirm.','Readings are simulated in this prototype. No real camera is used.','Go to Membership → How to cancel to end your demo membership.','All your demo records are saved in this browser only. You can export or delete them in Settings.'][i])}</p></details>`).join('')}</div><div class="card mt">${row('Contact support','','mail',"go('feedback','Contact support')")}${row('Send feedback','','message',"go('feedback')")}${row('Report an issue','','shield',"go('feedback','Report an issue')")}${row('About PulseFit','Version 1.0 · Interactive demo','leaf',"go('about')")}</div>`;
screens.feedback=()=>header(param||'We’re listening')+select('Issue type','issuetype',['Feedback','Technical issue','Account question','Other'],'Feedback')+`<label class="form-field"><span>${t('Tell us a little more')}</span><textarea id="feedback"></textarea></label><label class="form-field"><span>${t('Screenshot (optional)')}</span><input type="file" accept="image/*"></label>`+field('Contact email','contactemail',state.email,'email')+btn('Submit feedback',"if(!val('feedback').trim())toast('Please add a description');else{state.feedback=[...(state.feedback||[]),{type:val('issuetype'),text:val('feedback'),email:val('contactemail')}];save();go('feedbackSuccess')}");
screens.feedbackSuccess=()=>header('Thank you')+`<div class="screen-center"><div class="circle-icon">${icon('check')}</div><h2>${t('Your voice matters.')}</h2><p class="subtitle">${t('Your feedback has been saved locally for this demo. No message was sent to a support team.')}</p>${btn('Done',"nav('profile')")}</div>`;
screens.about=()=>header('About PulseFit')+`<div class="circle-icon">${icon('activity')}</div><h2 style="text-align:center">PulseFit</h2><p class="subtitle" style="text-align:center">${t('Build a healthier rhythm')}<br>2.0 · ${t('Interactive prototype')}</p><div class="card"><p>${t('Designed around small, sustainable habits: movement, awareness and a supportive community.')}</p></div>${btn('Replay onboarding',"startOnboarding()",'secondary mt')}${btn('Demo page states',"go('demoStates')",'secondary mt')}`;
// Search, notifications, export and sharing
const searchable=[...courses.map(c=>({label:c.name,type:'Workout',page:'workout',arg:c.name})),...exercises.map((c,i)=>({label:c,type:'Movement',page:'exercise',arg:String(i)})),...articles.map((c,i)=>({label:c[1],type:c[0],page:'article',arg:String(i)})),...seededPosts.map(p=>({label:p.name,type:'People',page:'user',arg:p.id})),{label:'7-day movement challenge',type:'Challenge',page:'challenge',arg:''},{label:'#SmallSteps',type:'Topic',page:'topic',arg:'SmallSteps'}];
screens.search=()=>header('Find your next step')+`<label class="form-field"><input id="searchquery" placeholder="${t('Workouts, people, little inspiration…')}" aria-label="${t('Search')}" oninput="searchResults(this.value)"></label>${state.searches.length?`<div class="row between"><h3>${t('Recent searches')}</h3>${btn('Clear',"state.searches=[];save();render()",'text-button')}</div><div class="chip-row">${state.searches.slice(0,4).map(s=>btn(esc(s),`document.getElementById('searchquery').value=this.textContent;searchResults(this.textContent)`,'chip')).join('')}</div>`:''}<div id="searchresults">${searchResultHtml('')}</div>`;
function searchResultHtml(q){let matches=searchable.filter(x=>(t(x.label)+' '+t(x.type)).toLowerCase().includes(q.toLowerCase()));return matches.length?`<div class="card">${matches.map(x=>row(x.label,x.type,'search',`openSearch('${x.page}','${x.arg}')`)).join('')}</div>`:`<div class="empty">${icon('search')}<h3>${t('No results just yet.')}</h3><p>${t('Try “flow”, “mobility” or “Sofia”.')}</p></div>`}
function searchResults(q){document.getElementById('searchresults').innerHTML=searchResultHtml(q)}
function openSearch(p,a){const q=val('searchquery').trim();if(q){state.searches=[q,...state.searches.filter(x=>x!==q)].slice(0,8);save()}go(p,a)}
const messages=[{id:1,title:'A little movement is waiting.',sub:'Your Full body flow is ready when you are.',type:'Workout',page:'workout'}, {id:2,title:'Your weekly perspective is ready.',sub:'Small steps. Real progress.',type:'System',page:'report'}, {id:3,title:'You’re in good company.',sub:'The 7-day movement challenge starts today.',type:'Community',page:'challenge'}];
screens.messages=()=>header('Your updates',ib('check',"state.read=messages.map(x=>x.id);save();render();toast('All updates marked as read')",'Mark all read'))+`<div class="chip-row">${['All','Workout','Community','System'].map(x=>btn(x,`filter='${x}';render()`,filter===x?'chip active':'chip')).join('')}</div><div class="card">${messages.filter(m=>!(state.deletedMessages||[]).includes(m.id)&&(filter==='All'||m.type===filter||!['Workout','Community','System'].includes(filter))).map(m=>`<div class="row">${row(m.title,m.sub,state.read.includes(m.id)?'check':'bell',`state.read.push(${m.id});save();go('${m.page}')`)}${ib('trash',`state.deletedMessages=[...(state.deletedMessages||[]),${m.id}];save();render()`,'Delete notification')}</div>`).join('')||`<div class="empty">${t('You’re all caught up.')}</div>`}</div>`;
function exportData(){downloadBlob('pulsefit-data.json',JSON.stringify(state,null,2),'application/json');toast('Your data export is ready')}
function downloadBlob(filename,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function share(title){window.shareTitle=title;sheet('Share a little good energy',title,btn('Copy link','copyLink()','secondary')+btn('Save image',`downloadCard(window.shareTitle)`,'secondary')+btn('More','nativeShare()','secondary')+btn('Cancel','closeSheet()','text-button'))}
async function copyLink(){try{await navigator.clipboard.writeText(location.href);toast('Link copied');closeSheet()}catch{sheet('Your share link','Copy this link to share the demo.',`<input readonly value="${esc(location.href)}" onclick="this.select()">`)}}
async function nativeShare(){if(navigator.share){try{await navigator.share({title:'PulseFit',text:t(window.shareTitle),url:location.href});closeSheet()}catch{}}else copyLink()}
function downloadCard(title){const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1100;const ctx=canvas.getContext('2d');ctx.fillStyle='#eaf2ff';ctx.fillRect(0,0,900,1100);ctx.fillStyle='#5968f2';ctx.fillRect(50,50,800,1000);ctx.fillStyle='#d9ff63';ctx.font='32px sans-serif';ctx.fillText('PULSEFIT',110,140);ctx.fillStyle='#ffffff';ctx.font='48px sans-serif';ctx.fillText(t(title).slice(0,29),110,290);ctx.font='38px sans-serif';ctx.fillText(state.name,110,375);ctx.fillStyle='#d9ff63';ctx.font='120px sans-serif';ctx.fillText(title.includes('certificate')?'7 / 7':title.includes('Heart')?String(state.hearts[0]?.value||72):'82 / 100',110,630);ctx.fillStyle='#c7cef2';ctx.font='26px sans-serif';ctx.fillText('Small steps. A lasting rhythm.',110,790);ctx.font='21px sans-serif';ctx.fillText('Demo data · September 2026',110,970);const a=document.createElement('a');a.download='pulsefit-share.png';a.href=canvas.toDataURL('image/png');a.click();toast('Your image is ready')}
screens.demoStates=()=>header('Demo page states')+`<p class="subtitle">${t('Explore the empty, loading and recovery states in this prototype.')}</p><div class="stack">${['Loading','Empty','Error','Offline','Permission denied','Sync failed','No search result','Deleted content','Private content','Subscription required'].map(x=>btn(x,`go('statePreview','${x}')`,'secondary')).join('')}</div>`;
screens.statePreview=()=>header(param)+`<div class="empty">${icon(param==='Offline'?'wifi':param==='Private content'?'shield':'leaf')}<h3>${t(param)}</h3><p>${t({'Empty':'Your first record starts here.','Error':'Something interrupted this moment. Let’s try again.','Offline':'You can still explore your saved demo data.','Permission denied':'You can change permissions in Settings.','Sync failed':'Your existing data is safe. Retry when you’re ready.','No search result':'Try a different keyword.','Deleted content':'This content is no longer available.','Private content':'This person is sharing with followers only.','Subscription required':'Explore Plus for more support.','Loading':'Bringing your rhythm together…'}[param])}</p>${param==='Loading'?'<div class="bar mt"><span style="width:65%;animation:breathe 1s infinite"></span></div>':btn(param==='Subscription required'?'Explore Plus':param==='Permission denied'?'Open settings':'Try again',param==='Subscription required'?"go('paywall')":param==='Permission denied'?"go('permissions')":"back();toast('Ready to continue')",'primary mt')}</div>`;
function afterRender(){document.querySelector('.device').classList.toggle('large-text',state.textSize==='Large');if(page==='splash')timer=setTimeout(()=>{page=state.loggedIn?(state.onboarded?'home':'intro'):'welcome';if(page==='intro'){flowMode='setup';setupStage=0;draftAnswers={...state,permissions:{...state.permissions}}}history.replaceState({page,param:''},'','#'+page);render()},900);if(page==='generating'){setTimeout(()=>{const b=document.getElementById('generatebar');if(b)b.style.width='100%'},30);timer=setTimeout(()=>{if(page==='generating')go('result')},2300)}if(page==='trainingHistory'){document.getElementById('historytype')?.addEventListener('change',filterHistory)}if(page==='player')timer=setInterval(()=>{if(paused)return;seconds--;let el=document.getElementById('timer');if(el)el.textContent='00:'+String(Math.max(0,seconds)).padStart(2,'0');if(seconds<=0){rest?endRest():nextExercise()}},1000);if(page==='measuring'&&!measureIssue)timer=setInterval(()=>{measureProgress++;const counter=document.getElementById('measurecount'),bar=document.getElementById('measurebar');if(counter)counter.textContent=15-measureProgress;if(bar)bar.style.width=measureProgress/15*100+'%';if(measureProgress>=15){state.pendingHeart=72;go('heartResult')}},1000)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('overlay').innerHTML?closeSheet():back()});

// Feature-detected structured tools share the same persistent state as the UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_pulsefit_demo_summary',description:'Read the locally saved demo wellness summary; no medical data is measured.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({workouts:state.workouts.length,heartReadings:state.hearts.length,weight:state.weight,joinedChallenge:state.joined,checkins:state.checkins})},{name:'navigate_pulsefit_demo',description:'Open one of the four main demo sections without completing any activity.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['home','plan','community','profile']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['home','plan','community','profile'].includes(input.section))throw new Error('Invalid section');nav(input.section);return {section:page}}}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
const activePlanScreen=screens.plan;
screens.plan=()=>state.planStatus==='deleted'?`<div class="row between"><h2>${t('Your plan')}</h2>${ib('settings',"go('planSettings')",'Plan settings')}</div><div class="empty">${icon('plan')}<h3>${t('Your next chapter starts here.')}</h3><p>${t('Create a new plan to begin again.')}</p>${btn('Create a new plan',"flowMode='newplan';draftAnswers={...state};onboardStep=0;go('onboarding')",'primary mt')}</div>`:activePlanScreen();
